('1515','baza_velebit_2026_appready','Amer 1',44.772849573744,15.0123547789046,'u_katastru','HR03082','u_katastru','jama','Ličko-senjska','Senj','Krasno','Hajdučki kukovi',12.0,12.0,NULL,'ok | Objekt u katastru','{"id": 1515, "name": "Amer 1", "cadastre_status": "u_katastru", "cadastral_number": "HR03082", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.772849573744, "lon": 15.0123547789046, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Hajdučki kukovi", "altitude_m": null, "depth_m": 12.0, "length_m": 12.0, "vertical_range_m": 12.0, "entrance_count": 1.0, "plate_number": "05-857", "main_entrance_status": null, "access_description": "Od Velikog loma prema Zavižanu makadamskom cestom. Prvo skretanje lijevo koje vodi do okretaljke, zatim planinarskom stazom preme Lubenovačkim vratima. Čim se staza počinje lagano uspinjati odmah skrenuti lijevo gore strmo prema vrhu grebena oko 1000 m u smjeru sjeverozapada. Na sedlu se nalazi zaravnanje u šumi odakle oko 100 m po stijenama prema vrhu kota 1583 m. Od vrha ulaz u jamu nalazi se 83 m zračne linije. Od ulaza jame azimut na vrh je 147 stupnja, a na kuću na Zavižanu 323 stupnja.", "technical_description": "Jednostavan vertikalni speleološki objekt. Jedno sidrište do dna. Ulaz je vrlo teško uočljiva pukotina u klekovini.", "research_perspective": true, "research_perspective_note": "potpuno istražen;", "last_research_year": 2019.0, "last_research_date": "05.08.2019.", "last_research_date_iso": "2019-08-05", "clubs": "SOV; BJBT; New Jersey Initial Response Team; Speleo Roznava", "survey_authors": "Mirka Šafarić - Vučko", "team_members": "Ana Bakšić; Mark Dickey; Jessica Van Ord; Judit Kovacz; Denes Akos Nagy", "hazards": "nema;", "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": null, "hydrogeology": null, "georef_record": null, "gps_tracklog": null, "note": null, "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-857','da',NULL,NULL,NULL),
('379','baza_velebit_2026_appready','Americana',44.7721702239083,14.9819367343379,'u_katastru','HR04569','na_provjeri','jama','Ličko-senjska','Senj','Krasno','Rožanski kukovi',38.0,41.0,NULL,'ok | Objekt na provjeri','{"id": 379, "name": "Americana", "cadastre_status": "u_katastru", "cadastral_number": "HR04569", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "na_provjeri", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7721702239083, "lon": 14.9819367343379, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Rožanski kukovi", "altitude_m": 1527.0, "depth_m": 38.0, "length_m": 41.0, "vertical_range_m": 38.0, "entrance_count": 1.0, "plate_number": "05-1082", "main_entrance_status": null, "access_description": "Od Rossijeve kolibe krenuti planinarskom stazom prema naselju Velike Brisnice. Nakon 600 m sa planinarske staze skrenuti na sjever u smjeru Gromovače. Nakon 500 m, jama se nalazi na rubu udoline jugozapadne strane Gromovače.", "technical_description": "Jednostavna jama sa snijegom na dnu. Na JZ strani ulaza u vertikalu postavljeno je dvostruko sidrište s kojeg linija ide skroz do dna ulazne vertikale, odakle je postavljeno jednostruko sidrište iznad snijega za osiguranje po sniježnoj padini. U nastavku vertikale oprema je 3 S pločice i 50 m užeta.", "research_perspective": false, "research_perspective_note": "potpuno istražen", "last_research_year": 2023.0, "last_research_date": "5.8.2023", "last_research_date_iso": "2023-08-05", "clubs": "SOV", "survey_authors": "Maja Marinić", "team_members": "Maja Marinić, Lukas Grbac Lacković, Olga Jerković Perić, Jakov Kožić", "hazards": "led", "pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "suh", "hydrogeology": "nema", "georef_record": null, "gps_tracklog": null, "note": null, "workflow_raw": "ok | Objekt na provjeri"}':