('1441','baza_velebit_2026_appready','Angst Höhle',44.7720705027519,14.9731081442718,'u_katastru','HR04570','na_provjeri','jama','Ličko-senjska','Senj','Krasno','Gromovača',12.5,16.0,NULL,'ok | Objekt na provjeri','{"id": 1441, "name": "Angst Höhle", "cadastre_status": "u_katastru", "cadastral_number": "HR04570", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "na_provjeri", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7720705027519, "lon": 14.9731081442718, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Gromovača", "altitude_m": 1451.0, "depth_m": 12.5, "length_m": 16.0, "vertical_range_m": 12.5, "entrance_count": 1.0, "plate_number": "05-1085", "main_entrance_status": null, "access_description": "Od Rossijeve kolibe ići na zapad planinarskom stazom koja vodi na Velike Brisnice. Nakon cca 1,7 km skrenuti sa staze na SZ na zaravnatom terenu. Zatim hodati u smjeru sjevera cca 300 m kroz vrtaču te na grebenu vrtače produžiti po izohipsi u smjeru SZ cca 200 m pa skrenuti u smjeru JZ i hodati 200 m. Jama se nalazi na obodu vrtače.", "technical_description": "Jednostavni speleološki objekt vertikalnog karaktera s jednim ulazom s tri otvora odvojena glonđama. Potrebna je oprema za jedno prirodno sidrište oko stabla i jedno međusidrište.", "research_perspective": false, "research_perspective_note": "potpuno istražen", "last_research_year": 2023.0, "last_research_date": "9.8.2023", "last_research_date_iso": "2023-08-09", "clubs": "SOV, SUKZ", "survey_authors": "Jurica Jagetić", "team_members": "Valentina Plemenčić, Jurica Jagetić, Barbara Domitrović", "hazards": "nema", "pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "suh", "hydrogeology": "nema", "georef_record": null, "gps_tracklog": null, "note": null, "workflow_raw": "ok | Objekt na provjeri"}'::jsonb,'sjeverni_vele