('748','baza_velebit_2026_appready','Atentat',44.7646904267674,14.9920365213021,'u_katastru','HR04574','na_provjeri','jama','Ličko-senjska','Senj','Krasno','Rožanski kukovi',14.8,17.3,NULL,'ok | Objekt na provjeri','{"id": 748, "name": "Atentat", "cadastre_status": "u_katastru", "cadastral_number": "HR04574", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "na_provjeri", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7646904267674, "lon": 14.9920365213021, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Rožanski kukovi", "altitude_m": 1620.0, "depth_m": 14.8, "length_m": 17.3, "vertical_range_m": 14.8, "entrance_count": 1.0, "plate_number": "05-1097", "main_entrance_status": null, "access_description": "Od Rossijeve kolibe hodati Premužićevom stazom na jug do prvog oštrog zavoja, gdje se skida sa staze i ide na istok po grebenu, između vrtača, po kojemu se hoda cca 350 m starom, slabo markiranom planinarskom stazom. Ulaz u jamu se nalazi na sjevernoj strani grebena.", "technical_description": "Jednostavni vertikalni objekt sa špiljskim i jamskim ulazom. Najjednostavnije je ući špiljskim ulazom preko zaglonđane kosine. Moguće je slobodno ispenjati, međutim skok je oko 2,5 m te je sigurnije opremiti jamu pomoću užeta od 15 m i prirodnog dvostrukog sidrišta oko glonđi ispred špiljskog ulaza.", "research_perspective": false, "research_perspective_note": "potpuno istražen", "last_research_year": 2023.0, "last_research_date": "10.8.2023", "last_research_date_iso": "2023-08-10", "clubs": "SOV", "survey_authors": "Borna Boban", "team_members": "Dora Troha, Gorana Perić, Borna Boban, Karla Tolić", "hazards": "krušljive stijene", "pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "nakapnica/prokapnica", "hydrogeology": "nema", "georef_record": null, "gps_tracklog": null, "note": null, "workflow_raw": "ok | Objekt na provjeri"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-1097','da',NULL,NULL,NULL),
('1220','baza_velebit_2026_appready','Avatar',44.7482231259524,15.0003831289386,'u_katastru','HR02353','u_katastru','jama','Ličko-senjska','Senj','Krasno','Krajačev kuk',170.0,332.0,NULL,'ok | Objekt u katastru','{"id": 1220, "name": "Avatar", "cadastre_status": "u_katastru", "cadastral_number": "HR02353", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7482231259524, "lon": 15.0003831289386, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Krajačev kuk", "altitude_m": null, "depth_m": 170.0, "length_m": 332.0, "vertical_range_m": 170.0, "entrance_count": 1.0, "plate_number": "05-533", "main_entrance_status": null, "access_description": "Krećemo sa Velikog Lubenovca planinarskim putem (koji nije održavan) prema Premužićevoj stazi. Prije spoja sa Premužićevom stazom skrećemo u šumu pod stijene Krajačevog kuka te onda pratimo usjek dok ne dođemo do ulaza u jamu.", "technical_description": "Jama se postavljena fiksevima φ 8mm. Nakon ulaza pukotinskog tipa koja se pruža u pravcu S-JI ulazimo u vertikalu od 78m na dnu koje se nalazi snijeg/led, možemo nastaviti pukotinom na S-SZ gdje nakon par metara ulazimo kroz mali otvor 1x1,5m u vertikalu P36, nakon koje slijedi mala polica i vertikala P51. Na dnu P51 nalazi se suženje iz kojeg se ne osjeća strujanje zraka. Na dnu P78 ako slijedimo pukotinski rasjed na J-JI ulazimo u P91 na čijem dnu ulazimo u kanal koji ima vidljive ostatke proširivanja na stijenkama kanala te nakon horizontalnog kanala, u kojem se djelomično provlačimo, dolazimo do najdubljeg dijela jame na dubini od 170 m gdje se nalazi posljednje istraženi kanal, kojeg treba iI dalje proširivati, ovo je mjesto iz kojeg se osjeća strujanje zraka.", "research_perspective": true, "research_perspective_note": "potrebno proširivanje;", "last_research_year": 2018.0, "last_research_date": null, "last_research_date_iso": null, "clubs": "SOV; SUE; SOŽ; DZRJ Ljubljana; ASAK; SUKZ", "survey_authors": "2018: Marijan Sutlović; 2017: Tanja Šinko; Matic di Batista 2014: Marko Rakovac", "team_members": "Marko Rakovac; Matic di Batista; Tanja Šinko; Marijan Sutlović; Matea Talaja; Valentina Plemenčić; Lovel Kukuljan; Edo Vričić; Stjepan Dubac; Marin Mustapić; Špela Borko; Marin Mašina; Dimitrije Dimitrijević; Ivačica Petrinjak; Mislav Habjanec; Matija Belač; Marko Ličko; Marina Grandić", "hazards": "nema;", "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": null, "hydrogeology": null, "georef_record": null, "gps_tracklog": null, "note": null, "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-533','da',NULL,NULL,NULL),
('851','baza_velebit_2026_appready','Bateryka',44.7653415462827,15.0358420227804,'u_katastru','HR03238','u_katastru','jama','Ličko-senjska','Senj','Krasno','Hajdučki kukovi',66.0,74.0,NULL,'ok | Objekt u katastru','{"id": 851, "name": "Bateryka", "cadastre_status": "u_katastru", "cadastral_number": "HR03238", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7653415462827, "lon": 15.0358420227804, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Hajdučki kukovi", "altitude_m": null, "depth_m": 66.0, "length_m": 74.0, "vertical_range_m": 66.0, "entrance_count": 1.0, "plate_number": "05-852", "main_entrance_status": null, "access_description": "U Krasnom polju se krene glavnom šumskom asfaltiranom cestom prema Velikom Lomu. Dolazi se do raskrižja koje je na oštrom zavoju i skrene se desno u smjeru Zavižana. Na ovom raskrižju se skreće s asfaltirane ceste na makadam koji vodi do Zavižana te je postavljena rampa na ulazu u makadam. Neposredno nakon što se prođe Mali Lom a prije lugarnice na Velikom lomu skrene se u lijevo u šumu (smjer JZ) odnosno prate se oznake koje su postavili speleolozi za put prema Lubuškoj i jami Nedam. Nakon 400 m skrene se s puta prema oštroj padni u smjeru JI. Ulaz u jamu lako je uočljiv kada se popne na padinu.", "technical_description": "Jednostavana vertikalna jama s dva otvora koja se spajaju na 20 m dubine i kroz oba se može spustiti s opremom. Kroz jedan otvor (otvor na kojem se ne nalazi pločica) dolazi se do police prekrivene lišćem i spuštanjem ulazi u malo širiji protor gdje se spoj s drugim otvorom i druga vertikala od 40 m. Na dnu se nalazi šira dvorana. Tehnički detalji ucrtani su na nacrtu. Za opremanje je potrebno oko 100 m užeta te te minimalno 6 kompleta (karabiner + pločica za fiks 8 mm).", "research_perspective": true, "research_perspective_note": "nastavlja se; potrebno prečkati prema uskoj pukotini", "last_research_year": 2000.0, "last_research_date": null, "last_research_date_iso": null, "clubs": "SOV; Hungary OSZ; Osmica", "survey_authors": "Marina Grandić", "team_members": "2018:Ana Bakšić;Hrvoje Petričević; Tatjana Vujnović; Damijan Belavić; Mark Colberson ; Domagoj Čajko; Geza Brautigan; Szegedi Laszlo Modor 2019:Domagoj Čajko; Géza Bräutigam; Szegedi Laszlo Modor; Marina Grandić; Damijan Belavić", "hazards": "nema;", "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": null, "hydrogeology": null, "georef_record": null, "gps_tracklog": null, "note": "Jama SOV-PL 7A nalazi se uz jamu BATERYJKA pa su koordinate položaja iste; Jama su prvi puta istražili poljski speleolozi 2000. godine (D.Cieszynski), međutim ne postoji nacrt objekta iz te godine. Kroz južni otvor jame do police se spustila ekipa 2018. i zabila pločicu. Ekipa 2019 spustila se kroz sjeverni ulaz kada je napravljen i nacrt jame", "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-852','da',NULL,NULL,NULL),
('1513','baza_velebit_2026_appready','Batorinka',44.767152022362,15.0310589091691,'u_katastru','HR03079','u_katastru','jama','Ličko-senjska','Senj','Krasno','Hajdučki kukovi',6.0,8.0,NULL,'ok | Objekt u katastru','{"id": 1513, "name": "Batorinka", "cadastre_status": "u_katastru", "cadastral_number": "HR03079", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.767152022362, "lon": 15.0310589091691, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Hajdučki kukovi", "altitude_m": null, "depth_m": 6.0, "length_m": 8.0, "vertical_range_m": 6.0, "entrance_count": 1.0, "plate_number": "05-919", "main_entrance_status": null, "access_description": "Iz Lomske dulibe prema Krasnu, 200 tinjak metara od skretanje za stazu prema Lukinoj jami. Kretanje po šumskom brdovitom terenu oko 30 minuta od ceste.", "technical_description": "jednostavan vertikalni speleološki objekt. Na dnu je zemlja.", "research_perspective": false, "research_perspective_note": "potpuno istražen;", "last_research_year": 2019.0, "last_research_date": "4-5.8.2019.", "last_research_date_iso": null, "clubs": "SOV", "survey_authors": "Darko Španja", "team_members": "Lucija Mihaljević; Igor Ivanković; Filip Pacak; Hrvoje Mihalinec;", "hazards": "nema;", "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": null, "hydrogeology": null, "georef_record": null, "gps_tracklog": null, "note": null, "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-919','da',NULL,NULL,NULL),
