('1279','baza_velebit_2026_appready','Begića jama',44.7658952113338,15.0229300382867,'krug_15',NULL,'krug_15','jama','Ličko-senjska','Senj','Krasno','Hajdučki kukovi',73.0,80.0,'zapisnik','fotka','{"id": 1279, "name": "Begića jama", "cadastre_status": "krug_15", "cadastral_number": null, "in_cadastre_bool": false, "not_in_cadastre_candidate": true, "record_status": "krug_15", "field_tasks": "zapisnik", "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7658952113338, "lon": 15.0229300382867, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Hajdučki kukovi", "altitude_m": 1510.0, "depth_m": 73.0, "length_m": 80.0, "vertical_range_m": 73.0, "entrance_count": 1, "plate_number": "05-211", "main_entrance_status": null, "access_description": "Jama se nalazi na Hajdučkim kukovima na sjevernom Velebitu. Ide se asfaltiranom cestom iz Krasna prema jugu (Alan); od centra Krasna (pilana) vozi se 14,4 km i na oštrom zavoju se skrene s asfaltirane ceste na makadam, gdje je postavljena rampa i turistička karta NP Sjeverni Velebit. Od rampe se ide još 4 km po makadamu a zatim skreće na jug u šumu gdje uzbrdo vodi markirana staza prema Lukinoj jami. Staza je dobro utabana i markirana čunjićima i plavim oznakama na stijenama. Od makadama se ide cca 400 m na jug a zatim se u kuloaru skrene na sjever i hoda još cca 75 m do ulaza u Lukinu jamu. Odande se ide dalje još cca 350 m prema jugozapadu po teškom krševitom terenu s klekovinom, bez hlada. Jama se nalazi iznad druge vrtače zapadno od Lukine jame.", "technical_description": null, "research_perspective": null, "research_perspective_note": null, "last_research_year": 2025, "last_research_date": "31.7.2025", "last_research_date_iso": "2025-07-31", "clubs": "SOV; SOM; SUKZ;", "survey_authors": "Krešimir Prskalo", "team_members": "Krešimir Prskalo; Mario Musulin; Ana Bakšić; Tomislav Bajo;", "hazards": null, "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": "da", "hydrology": null, "hydrogeology": "nema", "georef_record": "103589;Begića jama;383089.1870259237;4959494.863174749;0.7071067811865476", "gps_tracklog": null, "note": "sređeni nacrt u jako lošoj rezoluciji, probati naći original", "workflow_raw": "fotka"}'::jsonb,'sjeverni_velebit_2026_kml',FALSE,'05-211','da',NULL,NULL,'103589;Begića jama;383089.1870259237;4959494.863174749;0.7071067811865476'),
