('1241','baza_velebit_2026_appready','Borovnica',44.7807207921051,14.9874367191507,'u_katastru','HR05480','u_katastru','jama','Ličko-senjska','Senj','Krasno','Rožanski kukovi',51.9,112.1,NULL,'ok | Objekt na provjeri','{"id": 1241, "name": "Borovnica", "cadastre_status": "u_katastru", "cadastral_number": "HR05480", "in_cadastre_bool": true, "not_in_cadastre_candidate": true, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7807207921051, "lon": 14.9874367191507, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Rožanski kukovi", "altitude_m": 1495.0, "depth_m": 51.9, "length_m": 112.1, "vertical_range_m": 51.9, "entrance_count": 2.0, "plate_number": "05-323", "main_entrance_status": null, "access_description": "Pristup sa Zavižana: ići Premužićevom stazom prema jugu. Hodati cca 3 km, zatim skrenuti prema istoku prema Škrbinoj dragi. U prvoj vrtači je jama. Pristup s Rossijeve kolibe: ići Premužićevom stazom prema sjeveru (Zavižanu). Hodati cca 3-4 km i skrenuti prema istoku. Jama se nalazi 100 m istočno od Premužićeve staze.", "technical_description": "Jama s dva ulaza, međusobno udaljena oko 7 m, između ulaza je most. Jama je opremljena s 5 sidrišta, od kojih dva dvostruka. Zadnje sidrište vodi prema pukotini dubine oko 10 m, ali je zarušena. Između prvog ulaza i mosta je najviša točka dna koja se sastoji od zarušenog kamenja i vanjskog sedimenta. Ispod drugog ulaza nalaze se urušena debla, sediment i led. Daljnja perspektiva za istraživanje nalazi se uz rub ispod prvog ulaza i uz rub ispod drugog ulaza, ali je vrlo nesigurno. Jedan ulaz je oko 10 m viši.", "research_perspective": true, "research_perspective_note": "nastavlja se spuštanjem, nastavlja se provlačenjem, moguć nastavak u slučaju topljenja ledenog čepa", "last_research_year": 2024.0, "last_research_date": "3.8.2024", "last_research_date_iso": "2024-08-03", "clubs": "SOV, ASAK, SUKZ", "survey_authors": "Ana Pejović", "team_members": "Dragana Rajković, Ana Pejović, Damir Androić, Vinka Dubovečak", "hazards": "lažno dno, mogućnost urušavanja ili odrona, led", "pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "nakapnica/prokapnica", "hydrogeology": "nema", "georef_record": null, "gps_tracklog": null, "note": null, "workflow_raw": "ok | Objekt na provjeri"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-323','da',NULL,NULL,NULL),
