('987','baza_velebit_2026_appready','Crvuljak',44.7653006736807,14.9912247892896,'u_katastru','HR05164','u_katastru','jama','Ličko-senjska','Senj','Krasno','Rožanski kukovi',19.0,42.9,NULL,'ok | Objekt na provjeri','{"id": 987, "name": "Crvuljak", "cadastre_status": "u_katastru", "cadastral_number": "HR05164", "in_cadastre_bool": true, "not_in_cadastre_candidate": true, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7653006736807, "lon": 14.9912247892896, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Rožanski kukovi", "altitude_m": 1566.0, "depth_m": 19.0, "length_m": 42.9, "vertical_range_m": 19.0, "entrance_count": 1.0, "plate_number": "05-1140", "main_entrance_status": null, "access_description": "Jama se nalazi na JI obronku vrtače istočno od Premužićeve staze kod Rossijeve kolibe na sjevernom Velebitu. Od Rossijeve kolibe krenuti istočno 150 m prema dnu vrtače. Hodati po izohipsi kroz klekovinu 100 m. Jama se nalazi na vrhu usjeka popunjenog velikim glonđama.", "technical_description": "Jama ima jamski kružni ulaz, na dnu se nalaze glonđe. Pristupa se prirodnim sidrištem oko glonđi te se nastavlja dvostrukim sidrištem. Potrebna je gurtna, 20m užeta. S dna dvorane potrebno se popesti 1,5m, od tamo kreće spuštanje po siparu. Sipar je strm, ali ima dovoljno hvatova za ruke i noge te tehnička oprema nije potrebna. Na dnu sipara se nalazi mali otvor 0,5 x 0,5 m. Slijedećih 5m kreće se po još jednom siparu cca 5 m. Osjeti se cirkulacija zraka, ali objekt ovdje završava.", "research_perspective": false, "research_perspective_note": "potpuno istražen", "last_research_year": 2024.0, "last_research_date": "31.7.2024", "last_research_date_iso": "2024-07-31", "clubs": "SOV", "survey_authors": "Dora Troha", "team_members": "Dora Troha, Igor Dodolović, Roko Željem, Sebastian Barić", "hazards": "nema", "pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "suh", "hydrogeology": "nema", "georef_record": "318412;Crvuljak;380564.99999992305;4959473.999999889;0.7071067811865476", "gps_tracklog": null, "note": null, "workflow_raw": "ok | Objekt na provjeri"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-1140','da',NULL,NULL,'318412;Crvuljak;380564.99999992305;4959473.999999889;0.7071067811865476'),
