('843','baza_velebit_2026_appready','Dvije budale',44.7645286674936,14.9934176630145,'u_katastru','HR04620','na_provjeri','jama','Ličko-senjska','Senj','Krasno','Rožanski kukovi',11.1,13.2,NULL,'ok | Objekt na provjeri','{"id": 843, "name": "Dvije budale", "cadastre_status": "u_katastru", "cadastral_number": "HR04620", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "na_provjeri", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7645286674936, "lon": 14.9934176630145, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Rožanski kukovi", "altitude_m": 1632.0, "depth_m": 11.1, "length_m": 13.2, "vertical_range_m": 11.1, "entrance_count": 1.0, "plate_number": "05-1077", "main_entrance_status": null, "access_description": "Od Rossijeve kolibe hodati Premužićevom stazom na jug do prvog oštrog zavoja, gdje se skida sa staze i ide na istok po grebenu, između vrtača, po kojemu se hoda cca 400 m starom, slabo markiranom planinarskom stazom. Ulaz u jamu se nalazi netom s južne strane grebena, uz rub vrtače.", "technical_description": "Jednostavni vertikalni objekt. Za opremanje je potrebno uže od 20 m, jedna gurtna i karabiner za prirodno sidrište, jedan sidrišni komplet i devijator.", "research_perspective": false, "research_perspective_note": "potpuno istražen", "last_research_year": 2023.0, "last_research_date": "10.8.2023", "last_research_date_iso": "2023-08-10", "clubs": "SOV", "survey_authors": "Karla Tolić", "team_members": "Dora Troha, Gorana Perić, Borna Boban, Karla Tolić", "hazards": "krušljive stijene", "pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "suh", "hydrogeology": "nema", "georef_record": null, "gps_tracklog": null, "note": null, "workflow_raw": "ok | Objekt na provjeri"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-1077','da',NULL,NULL,NULL),
('888','baza_velebit_2026_appready','Dvojvchodova',44.7634823035948,15.0277286054323,'u_katastru','HR03839','u_katastru','jama sa špiljskim ulazom','Ličko-senjska','Senj','Krasno','Hajdučki kukovi',66.0,124.0,NULL,'ok | Objekt u katastru','{"id": 888, "name": "Dvojvchodova", "cadastre_status": "u_katastru", "cadastral_number": "HR03839", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama sa špiljskim ulazom", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7634823035948, "lon": 15.0277286054323, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Hajdučki kukovi", "altitude_m": 1480.0, "depth_m": 66.0, "length_m": 124.0, "vertical_range_m": 66.0, "entrance_count": 2.0, "plate_number": "05-217", "main_entrance_status": null, "access_description": "Ide se prema jami Nedam, zatim na Lubušku i od nje se skreće desno u vrtaču. U dnu strme vrtače je ulaz 1, a 3 m više ulaz 2.", "technical_description": "Jama sa špiljskim ulazom i jednim vertikalnim ulazom iznad. Za napredovanje je potrebno uže par metara nakon špiljskog ulaza. Ima puno leda na dnu.", "research_perspective": true, "research_perspective_note": "nastavlja se; led", "last_research_year": 2020.0, "last_research_date": "02.08.2020.", "last_research_date_iso": "2020-08-02", "clubs": "2020.: SOV; SD Pomir BiH; 2009.: SOV; 1993.: Slovaci", "survey_authors": "2020.: Ela Kovač ; 2009.: Goran Rnjak, Darko Bakšić, Marta Malenica; 1993.: M. Meško;", "team_members": "2020.: Maja Marinić; Katarina Azinović; Ela Kovač; Dejan Blaženović; 1993.: M. Meško; Dušan Kotlarčik; L. Ludhova; J. Šmoll;", "hazards": "krušljive stijene; led;", "pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "nakapmica", "hydrogeology": "nema", "georef_record": null, "gps_tracklog": null, "note": "Radili Slovaci 1993. Ponovljeno je crtanje 2009. i tad je jama imala 4 ulaza (?). Ponovno nacrtano 2020. kad jama opet ima 2 ulaza.", "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-217','da',NULL,NULL,NULL),
('1281','baza_velebit_2026_appready','Elinih 20',44.7694496329877,15.0249871233515,'u_katastru','HR04631','u_katastru','jama','Ličko-senjska','Senj','Krasno','Hajdučki kukovi',8.6,9.7,NULL,'ok | Objekt na provjeri','{"id": 1281, "name": "Elinih 20", "cadastre_status": "u_katastru", "cadastral_number": "HR04631", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7694496329877, "lon": 15.0249871233515, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Hajdučki kukovi", "altitude_m": 1450.0, "depth_m": 8.6, "length_m": 9.7, "vertical_range_m": 8.6, "entrance_count": 1.0, "plate_number": "05-901", "main_entrance_status": null, "access_description": "Od Lugarnice na Velikom Lomu (HTRS X=38247, Y=4960747) krene se makadamom jugoistočno u smjeru Krasnog. Nakon 900 skrene se u šumu strmo uzbrdo a nakon 200 m šuma prelazi u stjenovito područje. Teren je teško prohodan i izrazito strm. Jama nalazi 40-ak metara od završetka šume na manjem zaravnjenju, a ulaz u jamu je malih dimenzija i slabo uočljiv. Preporuča se da se do objekta dođe pomoću GPS uređaja.", "technical_description": "Jednostavni vertikalni objekt, pukotinskog oblika koja se pruža u smjeru I- Z. Ulaz je manjih dimenzija (0.5 m x 1.5 m) nakon čega sljedi manja vertikala (P 6) na dnu koje je polica. Na zapanom djelu police pukotina se nastavlja, međutim za daljnje istraživanje potrebno je proširiti uski dio. Osjeti se strujanje zraka.", "research_perspective": true, "research_perspective_note": "potrebno proširivanje", "last_research_year": 2025, "last_research_date": "4.8.2025", "last_research_date_iso": "2025-08-04", "clubs": "SOV; BJBT (Mađarska)", "survey_authors": "Marina Grandić", "team_members": "Ela Kovač; Ana Lipovac; Marina Grandić; Denes Nagy; Judit Kovacs", "hazards": "nema", "pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "nakapnica/prokapnica", "hydrogeology": "nema", "georef_record": null, "gps_tracklog": null, "note": "Jama je pukotina dubine 10 m, na kraju suženje iz kojeg puše. U blizini jame nalazi se zatrpan otvor (usmjeren suprotno od suženja) u kojem kamen pada 20m. Proširivanje je zatjevno.", "workflow_raw": "ok | Objekt na provjeri"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-901','da',NULL,NULL,NULL),
('891','baza_velebit_2026_appready','Ester',44.7563979077482,15.0345901518661,'u_katastru','HR03921','u_katastru','jama','Ličko-senjska','Senj','Krasno','Hajdučki kukovi',2020.0,87.5,NULL,'ok | Objekt u katastru','{"id": 891, "name": "Ester", "cadastre_status": "u_katastru", "cadastral_number": "HR03921", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7563979077482, "lon": 15.0345901518661, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Hajdučki kukovi", "altitude_m": 1446.0, "depth_m": 2020.0, "length_m": 87.5, "vertical_range_m": 85.1, "entrance_count": 1.0, "plate_number": "05-761", "main_entrance_status": null, "access_description": "Cestom od Krasnog prema Velikom Lomu, na oštrom zavoju (Punta) s lijeve strane šumskom vlakom uspinje se do vrha grebena. Nakon platoa ide se još cca 500 m u smjeru J - JI. Jama se nalazi na sjevernom rubu vrtače. Pristup jami je moguć s zapadne i južne strane (s istočne je visoka stijena).", "technical_description": "Jednostavni speleološki objekt - jama. Pukotinjskog je oblika i pruža se u smjeru SZ - JI. Ulaz s južne srane. Opremljena je fiksevima do dubine cca 80 m, gdje se nalazi ledeni čep. Jama ide dalje, treba doći i provjeriti je li se led otopio.", "research_perspective": true, "research_perspective_note": "nastavlja se spuštanjem; ledeni čep", "last_research_year": 2020.0, "last_research_date": "31.07.2020.", "last_research_date_iso": "2020-07-31", "clubs": "SOV", "survey_authors": "Gorana Perić", "team_members": "2020.: Gorana Perić; Ana Lipovac; Vedran Ferenčak; 1995.: Slovaci", "hazards": "led", "pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "nakapnica/prokapnica", "hydrogeology": "nema", "georef_record": "125597;Ester;383977.43961238704;4958408.093783062;7.0710678118654755", "gps_tracklog": null, "note": "Istraživali Slovaci 1995. Tada je jama nacrtana do dubine od 110 m. U međuvremenu su očito gromade leda pale s većih visina i napravile ledeni čep na 80 m dubine. Jama ide dalje, ali ne može se proći od leda.", "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-761','da',NULL,NULL,'125597;Ester;383977.43961238704;4958408.093783062;7.0710678118654755'),
