('895','baza_velebit_2026_appready','G1 Lor',44.7398245386211,15.0841154477072,'u_katastru','HR03754','u_katastru','jama','Ličko-senjska','Senj','Krasno','Kita Gavranuša',27.0,29.0,NULL,'ok | Objekt u katastru','{"id": 895, "name": "G1 Lor", "cadastre_status": "u_katastru", "cadastral_number": "HR03754", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7398245386211, "lon": 15.0841154477072, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Kita Gavranuša", "altitude_m": null, "depth_m": 27.0, "length_m": 29.0, "vertical_range_m": 27.0, "entrance_count": 1.0, "plate_number": "05-089", "main_entrance_status": null, "access_description": "Asfaltiranim putem ići do Careve Kuće. Kod C. K. skrenuti na istočni makadam. Voziti se makadamom do Kote i skrenuti lijevo. Nastaviti do okretaljke. Vožnja cca 15 min. od okretaljke, nastaviti jugoistočno. Nakon stare vlake dolazi se do kamenjara, jama je na desnoj strani.", "technical_description": "Meandrasti ulaz nakon kojeg se pruža vertikala, jedno sidrište do dna, files 8 mm.", "research_perspective": false, "research_perspective_note": "potpuno istražen;", "last_research_year": 2020.0, "last_research_date": "27.07.2020.", "last_research_date_iso": "2020-07-27", "clubs": "SOV; SUKZ", "survey_authors": "Helena Polšek", "team_members": "Helena Polšek; Vinka Dubovečak; Damir Androić", "hazards": "nema", "pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "suh", "hydrogeology": "nema", "georef_record": "125240;G 1-LOR;387857.5920575574;4956447.838052976;0.7071067811865476", "gps_tracklog": null, "note": null, "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-089','da',NULL,NULL,'125240;G 1-LOR;387857.5920575574;4956447.838052976;0.707106781