('1276','baza_velebit_2026_appready','Hajdučka peć',44.7597047088878,14.9920399256135,'u_katastru','HR04659','na_provjeri','špilja','Ličko-senjska','Senj','Krasno','Rožanski kukovi',0.0,32.7,NULL,'ok | Objekt na provjeri','{"id": 1276, "name": "Hajdučka peć", "cadastre_status": "u_katastru", "cadastral_number": "HR04659", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "na_provjeri", "field_tasks": null, "object_type_final": "špilja", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7597047088878, "lon": 14.9920399256135, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Rožanski kukovi", "altitude_m": 1543.0, "depth_m": 0.0, "length_m": 32.7, "vertical_range_m": 12.0, "entrance_count": 1.0, "plate_number": "05-1091", "main_entrance_status": null, "access_description": "Od Rossijeve kolibe hodati Premužićevom stazom u smjeru Crikvene te 200 m nakon vrsha Crikvene skrenuti sa staze u šumu u smjeru istoka i nastaviti hodati cca 250 m. Zatim skrenuti u smjeru sjevera, preći greben između vrtača i hodati u smjeru sjeverozapada još 100 m. Ulaz se nalazi u stijeni na sjevernoj strani vrtače iznad čistine.", "technical_description": "Za prilaz ulazu potrebno je popeti penj od 10-ak m koji se može popeti tehnički te je na ulazu u objekt ostavljen ring. Špilja se nakon ulazne dvorane grana u dva kratka horizontalna kanala. U stropu špilje nalazi se djelomično zaglonđani otvor.", "research_perspective": false, "research_perspective_note": "potpuno istražen", "last_research_year": 2023.0, "last_research_date": "10.8.2023", "last_research_date_iso": "2023-08-10", "clubs": "SOV, SOL", "survey_authors": "Ana Ercegovac", "team_members": "Valentina Plemenčić, Barbara Domitrović, Ana Ercegovac, Čedo Josipović, Luka Bogdanić", "hazards": "nema", "pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "nakapnica/prokapnica", "hydrogeology": "ne