),
('1394','baza_velebit_2026_appready','Hrvatska stotka',44.7659175037815,15.0344378721091,'u_katastru','HR02375','u_katastru','jama','Ličko-senjska','Senj','Krasno','Punta',106.0,29.0,NULL,'ok | Objekt u katastru','{"id": 1394, "name": "Hrvatska stotka", "cadastre_status": "u_katastru", "cadastral_number": "HR02375", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7659175037815, "lon": 15.0344378721091, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Punta", "altitude_m": 1330.0, "depth_m": 106.0, "length_m": 29.0, "vertical_range_m": 106.0, "entrance_count": 1.0, "plate_number": "05-853", "main_entrance_status": null, "access_description": "Autom od Krasnog polja cestom prema Lomskoj dulibi. Iza oštrih zavoja na makadamskoj cesti (iza djela ceste, na karti označenog- Punta) sa lijeve strane ceste nalazi se šumska vlaka. Tom vlakom uspinje se do kraja zatim se nastavi u smjeru J-JI do malog platoa na kojem se između kamenih glondži nalazi ljevkasti ulaz. Od glavnog makadamskog puta do jame udaljenost je oko 250 m", "technical_description": "Jednostavan vertikalni speleološki objekt kojeg čini jedna vertikala od 97 m. Na 60-tom m dubine nalazi se jedan dolazni dimnjak, odnosno kanal koji završava usponom. Sličan odvojak nalazi se i neposredno iznad dna. Na dnu se nalazi snježni sipar. Kanal povratno zavija i završava slijepo.", "research_perspective": true, "research_perspective_note": "nastavlja se penjanjem; potrebno proširivanje;", "last_research_year": null, "last_research_date": null, "last_research_date_iso": null, "clubs": "SOV; SDH; SOŽ; SO Zagreb-Matica; SD Ursus Spelaeus", "survey_authors": "Hrvatska stotka 1997: Tanja Bizjak Jama 72 1984: Jadranko Ostojić", "team_members": "Ronald Železinjak; Darko Bakšić; Ivan Glavaš; Tanja Bizjak; Jadranko Ostojić; Aljoša Kononenko; Damir Horvat", "hazards": "nema;", "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "nakapnica/prokapnica", "hydrogeology": "nema", "georef_record": null, "gps_tracklog": null, "note": "0", "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-853','da',NULL,NULL,NULL),
