('904','baza_velebit_2026_appready','Iliberis',44.7642408639142,15.0265345262111,'nije_u_katastru',NULL,'nije_u_katastru','jama','Ličko-senjska','Senj','Krasno','Hajdučki kukovi',2021.0,80.0,'ponoviti_nacrt','ponoviti nacrt | Ponoviti nacrt','{"id": 904, "name": "Iliberis", "cadastre_status": "nije_u_katastru", "cadastral_number": null, "in_cadastre_bool": false, "not_in_cadastre_candidate": true, "record_status": "nije_u_katastru", "field_tasks": "ponoviti_nacrt", "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7642408639142, "lon": 15.0265345262111, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Hajdučki kukovi", "altitude_m": 1495.0, "depth_m": 2021.0, "length_m": 80.0, "vertical_range_m": null, "entrance_count": 1.0, "plate_number": "05-220", "main_entrance_status": null, "access_description": "Ide se cestomo od Krasna prema Velikom Lomu. Nakon prolaska rampe te još vožnje po makadamu, ide se pješice, prije Velikog Loma. Postoje dva pristupa: prvi je pristup preko Trojame slijedeći čunjiće za Lukinu jamu-Trojamu te dalje po azimutu do Iliberis. Drugi pristup: preko isturenog bivka od jame Nedam te dalje po azimutu do jame Iliberis.", "technical_description": "Jama se nalazi u vrtači. Nakon inicijalne vertikale dolazi se do snježne kape te se otuda uz zid nastavlja ledom obloženi kanal. Završava se u snijegu i ledu.", "research_perspective": true, "research_perspective_note": "nastavlja se spuštanjem; led", "last_research_year": 2021.0, "last_research_date": "29.7.2021.", "last_research_date_iso": "2021-07-29", "clubs": "2021: SOV; 2010: SOV; Španjolci", "survey_authors": "Ana Lipovac; Lukas Grbac Lacković;", "team_members": "2021: Ana Lipovac, Lukas Grbac Lacković, Marko Ličko, Barbara Domitrović, Dalibor Paar, Čedo Josipović, Paul Karoshi 2010: Matija Čepelak; Marta Malenica; Ivan Turčin;", "hazards": "led", "pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": "da", "hydrology": "suh", "hydrogeology": "nema", "georef_record": null, "gps_tracklog": null, "note": "postoji tlocrt ali samo do 100 m, dalje nema tlocrta. Promijeniti pločicu (duplić!)", "workflow_raw": "ponoviti nacrt | Ponoviti nacrt"}'::jsonb,'sjeverni_velebit_2026_kml',FALSE,'05-220','da',NULL,NULL,NULL),
