nema", "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "suh", "hydrogeology": "nema", "georef_record": null, "gps_tracklog": null, "note": null, "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-829','da',NULL,NULL,NULL),
