('497','baza_velebit_2026_appready','Ledena jama u Lomskoj dulibi S.U.K',44.7729788210649,15.0271840735705,'nije_u_katastru',NULL,'nije_u_katastru','jama','Ličko-senjska','Senj','Krasno','Veliki Lom',536.0,629.0,'fotka','fotka','{"id": 497, "name": "Ledena jama u Lomskoj dulibi S.U.K", "cadastre_status": "nije_u_katastru", "cadastral_number": null, "in_cadastre_bool": false, "not_in_cadastre_candidate": true, "record_status": "nije_u_katastru", "field_tasks": "fotka", "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7729788210649, "lon": 15.0271840735705, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Veliki Lom", "altitude_m": 1235.0, "depth_m": 536.0, "length_m": 629.0, "vertical_range_m": 514.0, "entrance_count": 1.0, "plate_number": "05-0004", "main_entrance_status": null, "access_description": "Od planinarskog doma na vučjaku, cestom u veliki lom. Od šumarske kuće dalje cestom do pred kraj dulibe, tj. Do šume. Skrenuti u dulibu. Otvor jame vidljiv je sa ceste kao vrtača.", "technical_description": "Ulaz u jamu izgleda kao velika vrtača, koja se spušta vertikalno prema dolje. Na dubini od 40 m nalazi se veliki ledeni čep. Na sjevernoj strani uz stijenu otvorio se prolaz u ledu vertikalno prema dolje. Led i snijeg spuštaju se do dubine od oko 90 m gdje se nalazi kameni sipar, a iza vertikala od 190 m. Tu se nalazi velika kosa dvorana dimenzija 75 x 45 m. U dnu dvorane u pravcu sz nalazi se otvor u vertikalu koja se spušta do -451 m gdje se nalazi suženje. Nakon suženja vertikala od 63 m svladana je s četiri spita. Tu je prisutna jaka nakapnica. Dno je prekriveno kršjem između kojeg se gubi voda.", "research_perspective": true, "research_perspective_note": "da", "last_research_year": 2025, "last_research_date": "21.7.1996", "last_research_date_iso": "1996-07-21", "clubs": "SOŽ; SOD; SOV", "survey_authors": "Branko Jalžić; (1977) B. Šmida; (1993.) Igor Jelinić (1996.)", "team_members": null, "hazards": null, "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": "da", "hydrology": null, "hydrogeology": null, "georef_record": null, "gps_tracklog": null, "note": "Postoje Slovački i naš nacrt koji se razlikuju u dubini za 19m.", "workflow_raw": "fotka"}'::jsonb,'sjeverni_velebit_2026_kml',FALSE,'05-0004','da',NULL,NULL,NULL),
