al_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "nakapnica/prokapnica", "hydrogeology": "nema", "georef_record": "309507;Milord;383840.99999993347;4958760.999999906;0.7071067811865476", "gps_tracklog": null, "note": "mrtva ovca na dnu", "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-951','da',NULL,NULL,'309507;Milord;383840.99999993347;4958760.999999906;0.7071067811865476'),
