pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "suha", "hydrogeology": "nema", "georef_record": "306497;Napuknuta;383828.99999993335;4958748.999999906;0.7071067811865476", "gps_tracklog": null, "note": null, "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-1008','da',NULL,NULL,'306497;Napuknuta;383828.99999993335;4958748.999999906;0.7071067811865476'),
