('1323','baza_velebit_2026_appready','Pan Pek',44.7539165708698,15.0076876180332,'nije_u_katastru',NULL,'nije_u_katastru','špilja s jamskim ulazom','Ličko-senjska','Senj','Krasno','Rožanski kukovi',8.2,18.3,'fotka;koordinate','fotka, koordinate','{"id": 1323, "name": "Pan Pek", "cadastre_status": "nije_u_katastru", "cadastral_number": null, "in_cadastre_bool": false, "not_in_cadastre_candidate": true, "record_status": "nije_u_katastru", "field_tasks": "fotka;koordinate", "object_type_final": "špilja s jamskim ulazom", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7539165708698, "lon": 15.0076876180332, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Rožanski kukovi", "altitude_m": null, "depth_m": 8.2, "length_m": 18.3, "vertical_range_m": null, "entrance_count": 1.0, "plate_number": "029-009", "main_entrance_status": null, "access_description": "Pristup je u zapisniku, ja sam ga u nemogucnosti iscitati", "technical_description": null, "research_perspective": true, "research_perspective_note": "ne", "last_research_year": 2015.0, "last_research_date": "04.08.2015.", "last_research_date_iso": "2015-08-04", "clubs": "SO PDS Velebit; SU Međimurje", "survey_authors": "Drago Novak, Darko Španja", "team_members": null, "hazards": null, "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": "ne", "hydrology": null, "hydrogeology": null, "georef_record": null, "gps_tracklog": null, "note": "Nemogu nac fotografiju ulaza,zapisničar je vjerojatno darko španja al ne piše.", "workflow_raw": "fotka, koordinate"}'::jsonb,'sjeverni_velebit_2026_kml',FALSE,'029-009','da',NULL,NULL,NULL),
('543','baza_velebit_2026_appready','Patkov gušt',44.7571305391605,15.0236965143375,'u_katastru','HR01456','u_katastru','jama','Ličko-senjska','Senj','Krasno','Gornji kuk; Hajdučki kukovi',553.0,601.0,NULL,'ok | Objekt u katastru','{"id": 543, "name": "Patkov gušt", "cadastre_status": "u_katastru", "cadastral_number": "HR01456", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7571305391605, "lon": 15.0236965143375, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Gornji kuk; Hajdučki kukovi", "altitude_m": 1450.0, "depth_m": 553.0, "length_m": 601.0, "vertical_range_m": 553.0, "entrance_count": 1.0, "plate_number": "05-0003", "main_entrance_status": null, "access_description": "Jama se nalazi u strogom prirodnom rezervatu Hajdučki i Rožanski kukovi na sjevernom Velebitu, 150 m sjeverno od Gornjeg kuka. Najlakši pristup je s Velikog Lubenovca gdje se može postaviti bazni logor. Jama se nalazi u vrletnom terenu gdje ne postoje planinarske staze i teško je preciznije opisati put do jame. Putem se od Velikog Lubenovca prolazi kroz izrazito težak teren Jurekovca koji prepun vrtača i orijentacija je otežana. Drugi mogući put je makadamskom cestom od Velikog Lubenovca prema Lubenovačkim vratima. Sa ceste se skreće desno na planinarski put prema Hajdučkim kukovima. Sa puta sa skreće desno u područje Gornjeg kuka. Jama je impozantnog ulaza u vrtači.", "technical_description": "Vrtača u čijem se zapadnom dijelu nalazi otvor jame nepravilnog je oblika, izdužena u smjeru S-J, dimenzija oko 100 x 75 m. Sam otvor jame velik je oko 65 x 30 m. U jamu se ulazi sa zapadne strane otvora, gdje se u maloj depresiji nalaze veliki kameni blokovi. Na rubu otvora nalazi se markantno stablo smreke. Stijena je krušljiva, što predstavlja veliku opasnost za speleologe u nižim dijelovima jame. Na dubini od 65 m nalazi se ledena kosina kojom se spušta ispod prvog ledenog čepa, debljine oko 15 m. Jama se i dalje preko snijega i leda spušta do dubine od 105 m, gdje je prolaz u ledu dimenzija 2 x 1,5 m. To suženje, kroz koje 2000. godine nije bilo moguće proći zbog velike količine snijega i leda, najuže je mjesto u jami. Do ovog mjesta dopire dnevna svjetlost, a zbog topljenja leda tu počinje i jako kapanje vode koje se kasnije pojačava, pa voda curi do samog dna jame. Nakon 130 m dubine jama se širi i približno istog profila spušta sve do dna. Stijene su potpuno ili djelomično prekrivene ledenom prevlakom sve do 300 m dubine, pa njeno odlamanje predstavlja stalnu opasnost. Na dubini od 465 m u stijeni se nalazi uska galerija na kojoj se može sigurno stajati. Jama završava dvoranom dimenzija 40 x 30 m. Ispod vertikale nalazi se veća količina snijega. Na sjevernom dijelu dvorane nalazi se najniža točka objekta - mali blatni odvojak u kojem se voda procjeđuje između kamenja i blata (Bakšić 1997; Bakšić 1998).", "research_perspective": true, "research_perspective_note": "potpuno istražen", "last_research_year": 2025, "last_research_date": "6.8.2025", "last_research_date_iso": "2025-08-06", "clubs": "SO PDS Velebit; Speleoklub Had Poreč (SKH)", "survey_authors": "Damir Lacković; Darko Bakšić; Ljiljana Josipović Novosel", "team_members": "Marko Andreis; Darko Bakšić; Tanja Bizjak; Dean Bratušek; Ana Čop; Tihana Dasović; Ivana Gregorić; Marko Grgin; Nataša Josipović; Damir Lacković; Tomislav Marić; Mislav Marohnić; Jagoda Munić; Ljiljana Novosel Josipović; Mladen Novosel; Davor Perić; Ivica Radić; Siniša Rešetar; Ana Katarina Sansević; Leonara Smirnjak; Irina Stipanović; Ana Bakšić; Vedran Šimunović; Darko Štefanac; Darko Troha; Vedran Vračar; Ivančica Zovko; Ronald Železnjak; Ivan Glavaš", "hazards": "krušljive stijene; led;", "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": null, "hydrogeology": null, "georef_record": null, "gps_tracklog": null, "note": "http://speleologija.eu/patkovgust/index.html http://speleologija.eu/patkovgust/index2008.html", "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-0003','da',NULL,NULL,NULL),
('1530','baza_velebit_2026_appready','Patnja hladnog Werthera',44.7708128192898,15.0066208042276,'u_katastru','HR03299','u_katastru','jama','Ličko-senjska','Senj','Krasno','Hajdučki kukovi',15.2,25.5,NULL,'ok | Objekt u katastru','{"id": 1530, "name": "Patnja hladnog Werthera", "cadastre_status": "u_katastru", "cadastral_number": "HR03299", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7708128192898, "lon": 15.0066208042276, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Hajdučki kukovi", "altitude_m": null, "depth_m": 15.2, "length_m": 25.5, "vertical_range_m": 15.2, "entrance_count": 1.0, "plate_number": "05-1024", "main_entrance_status": null, "access_description": "Prvo skretanje lijevo od Velikog loma prema Zavižanu parkirati kod okretaljke kod Škrbine drage i krenuti planinarskim putem prema Lubenačkim vratima. Ući u prvu vrtaču s lijeve strane.", "technical_description": "Potrebna speleološka oprema i uže duljine oko 30 m. Postavljena 2 sidrišta (na ulazu i međusidrište).", "research_perspective": false, "research_perspective_note": "potpuno istražen;", "last_research_year": 2019.0, "last_research_date": "02.08.2019.", "last_research_date_iso": "2019-08-02", "clubs": "SOV; SUKZ; W.F.Hohlenforschung Hohlenbaren", "survey_authors": "Valentina Kraš", "team_members": "Antonela Barbir; Luka Havliček; Marin Mašina; Tin Novosel; Paul Karoshi; Mislav Habijanec; Valentina Kraš", "hazards": "led;", "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": null, "hydrogeology": null, "georef_record": null, "gps_tracklog": null, "note": "zaleđeno dno, paziti na ledenu sigovinu. Jama se nalazi na obodu vrtače", "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-1024','da',NULL,NULL,NULL),
