('1321','baza_velebit_2026_appready','Pozoj',44.7561661176804,15.0083496516188,'u_katastru','HR02266','u_katastru','jama','Ličko-senjska','Senj','Krasno','Mali kuk; Rožanski kukovi',145.0,222.0,NULL,'ok | Objekt u katastru','{"id": 1321, "name": "Pozoj", "cadastre_status": "u_katastru", "cadastral_number": "HR02266", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7561661176804, "lon": 15.0083496516188, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Mali kuk; Rožanski kukovi", "altitude_m": null, "depth_m": 145.0, "length_m": 222.0, "vertical_range_m": 145.0, "entrance_count": null, "plate_number": "029-003", "main_entrance_status": null, "access_description": "Cestom prema lubenovačkim vratima do velike glonđe sa dvije planinarske oznake, skreće se lijevo preko korita pa strmo uzbrdo držeći se prema desno. Nakon 15 minuta uspona, kada se dođe do litice skrenut desno uzbrdo. Pratit livadu do vrtače pa prije početka vrtače popest se uz stijenu desno prije vertikale i pratit stijene. Prepenjat nabor 5 minuta s lijeve strane počinje usijek u kojem se nalazi jama.", "technical_description": "Jednostavni vertikalna jama sa dva otvora. Potrebno je 100 m špage do leda (postavljena 4 sidrišta sa fiksevima 8mm). Za daljnje napredovanje i istraživanje potrebno je još minimalno 100 m špage.", "research_perspective": true, "research_perspective_note": "nastavlja se spuštanjem;", "last_research_year": 2015.0, "last_research_date": "28.7.2015.", "last_research_date_iso": "2015-07-28", "clubs": null, "survey_authors": "Drago Novak,Andrija Perušić", "team_members": null, "hazards": null, "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "nakapnica/prokapnica", "hydrogeology": "nema", "georef_record": null, "gps_tracklog": null, "note": "Postoji opasnost od zarušavanja ledenih siga i blokova", "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'029-003','da',NULL,NULL,NULL),
