('898','baza_velebit_2026_appready','Pride rock',44.7708752298413,14.9990262856705,'u_katastru','HR05057','u_katastru','jama','Ličko-senjska','Senj','Krasno','Vratarski kuk, Rožanski kukovi',10.0,21.5,NULL,'ok | Objekt na provjeri','{"id": 898, "name": "Pride rock", "cadastre_status": "u_katastru", "cadastral_number": "HR05057", "in_cadastre_bool": true, "not_in_cadastre_candidate": true, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7708752298413, "lon": 14.9990262856705, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Vratarski kuk, Rožanski kukovi", "altitude_m": 1480.0, "depth_m": 10.0, "length_m": 21.5, "vertical_range_m": 10.0, "entrance_count": 1.0, "plate_number": "05-1136", "main_entrance_status": null, "access_description": "Ići automobilom od Krasna preko Lomske dulibe do Škrbine drage. Kod okretišta na Škrbinoj dragi ići planinarskom stazom prema Rossijevoj kolibi i hodati 1 km uzbrdo. Zatim skrenuti izvan staze prema JI. Teren je teže pristupačan, kršovit. Prvi dio je u šumi, drugi dio je otvoreni stijenjak. Oko 100-200 m je potrebno hodati do jame.", "technical_description": "Pukotinski objekt ispunjen glonđama. Tri ulaza, od čega dva prohodna za ljude. Kroz ulaz se nastavlja vertikala duga 10 m omeđena glonđama i krušljivim stijenama. Od dna vertikale u smjeru SI nastavlja se prema površini uski kanal omeđen glonđama koji završava neprohodnim pukotinskim ulazom. Kroz treći ulaz u sredini dim. 1x1 m može se kroz glonđe doći do iznad dvoranice na dnu jame. Na najvećem ulazu može se postaviti dvostruko sidrište i devijator da se izbjegnu krušljive stijene.", "research_perspective": false, "research_perspective_note": "potpuno istražen", "last_research_year": 2024.0, "last_research_date": "2.8.2024", "last_research_date_iso": "2024-08-02", "clubs": "SOV, ASAK, SUKZ", "survey_authors": "Ema Buljan", "team_members": "Ema Buljan, Hrvoje Đurinski, Sebastian Barić, Ana Pejović, Damir Androić, Vinka Dubovečak", "hazards": "krušljive stijene", "pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "suh", "hydrogeology": "nema", "georef_record": null, "gps_tracklog": null, "note": null, "workflow_raw": "ok | Objekt na provjeri"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-1136','da',NULL,NULL,NULL),
