('1053','baza_velebit_2026_appready','Prvi Spit',44.763317232403,15.0247010837665,'krug_15',NULL,'krug_15','jama','Ličko-senjska','Senj','Krasno','Hajdučki kukovi',202.3,20.0,'pronaci','fotka, koordinate, pločica | Fotka, koordinate, pločica','{"id": 1053, "name": "Prvi Spit", "cadastre_status": "krug_15", "cadastral_number": null, "in_cadastre_bool": false, "not_in_cadastre_candidate": true, "record_status": "krug_15", "field_tasks": "pronaci", "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.763317232403, "lon": 15.0247010837665, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Hajdučki kukovi", "altitude_m": 1460.0, "depth_m": 202.3, "length_m": 20.0, "vertical_range_m": 202.3, "entrance_count": 1.0, "plate_number": "05-1195", "main_entrance_status": null, "access_description": "Jama se nalazi na Hajdučkim kukovima na sjevernom Velebitu. Ide se asfaltiranom cestom iz Krasna prema jugu (Alan); od centra Krasna (pilana) vozi se 14,4 km i na oštrom zavoju se skrene s asfaltirane ceste na makadam, gdje je postavljena rampa i turistička karta NP Sjeverni Velebit. Od rampe se ide još 4 km po makadamu a zatim skreće na jug u šumu gdje uzbrdo vodi markirana staza prema Lukinoj jami. Staza je dobro utabana i markirana čunjićima i plavim oznakama na stijenama. Od makadama se ide cca 400 m na jug do kuloara gdje se račvaju staze za Lukinu jamu i Trojamu i zatim se ide dalje na jug prema Trojami još 90 m. Od Trojame se dalje ide na jugozapad 290 m, pa na jug 400 m po rubu šume do ulaza u jamu koji je velik i lako uočljiv.", "technical_description": null, "research_perspective": false, "research_perspective_note": "ne", "last_research_year": 2025, "last_research_date": "2.8.2025", "last_research_date_iso": "2025-08-02", "clubs": "SOV, SOŽ, SOSvM; SOM; SO Profunda; PK Sofia (Bugarska);", "survey_authors": "Tanja Bizjak", "team_members": "1994: Ana Predović; Lovro Hrust; Bruno Pintar; Tanja Bizjak; 2010: Goran Rnjak, Ivan Limić, Davor Cvitanić", "hazards": null, "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": "ne", "hydrology": null, "hydrogeology": null, "georef_record": "321116;Prvi spit;383210.99999993155;4959204.999999903;0.7071067811865476", "gps_tracklog": null, "note": null, "workflow_raw": "fotka, koordinate, pločica | Fotka, koordinate, pločica"}'::jsonb,'sjeverni_velebit_2026_kml',FALSE,'05-1195','da',NULL,NULL,'321116;Prvi spit;383210.99999993155;4959204.999999903;0.7071067811865476'),
