('1325','baza_velebit_2026_appready','Pusi',44.7540937546392,15.0095396868321,'u_katastru','HR04869','na_provjeri','špilja s jamskim ulazom','Ličko-senjska','Senj','Krasno','Rožanski kukovi',5.4,21.3,NULL,'ok | Objekt na provjeri','{"id": 1325, "name": "Pusi", "cadastre_status": "u_katastru", "cadastral_number": "HR04869", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "na_provjeri", "field_tasks": null, "object_type_final": "špilja s jamskim ulazom", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7540937546392, "lon": 15.0095396868321, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Rožanski kukovi", "altitude_m": 1432.0, "depth_m": 5.4, "length_m": 21.3, "vertical_range_m": 5.4, "entrance_count": 1.0, "plate_number": "029-002", "main_entrance_status": null, "access_description": "Cestom prema lubenovečkim vratima iz smjera velikog lubenovca do velikeglonđe s dvije planinarske oznake. Skreće se lijevo preko korita pa strmo uzbrdo držećise prema desno.Nakon 15-tak minuta uspona kada se dođe do litice, skrenut lijevo uzbrdo.Nakon 20tak minuta uspona s lijeve strane se otvara strmi spust prema jami.", "technical_description": "Kroz uski procjep u stijeni ulazi se jamskim skokom nakon kojeg se moguće kretati po špilji bez opreme. Glavni kanal se pruža u smjeru SZ-JI. Na samom kraju špilje nalazi se i jamski ulaz dim. 0,5 x 0,5 m.", "research_perspective": false, "research_perspective_note": "potpuno istražen", "last_research_year": 2015.0, "last_research_date": "27.7.2015.", "last_research_date_iso": "2015-07-27", "clubs": "SOV;SUM", "survey_authors": "Nikola Pongrac", "team_members": null, "hazards": "nema", "pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "suh", "hydrogeology": "nema", "georef_record": null, "gps_tracklog": null, "note": "prepraviti nacrt", "workflow_raw": "ok | Objekt na provjeri"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'029-002','da',NULL,NULL,NULL),
('1516','baza_velebit_2026_appready','Rafaelo',44.7722654008164,15.0117254400185,'u_katastru','HR03257','u_katastru','jama','Ličko-senjska','Senj','Krasno','Hajdučki kukovi',10.0,14.0,NULL,'ok | Objekt u katastru','{"id": 1516, "name": "Rafaelo", "cadastre_status": "u_katastru", "cadastral_number": "HR03257", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7722654008164, "lon": 15.0117254400185, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Hajdučki kukovi", "altitude_m": 1561.0, "depth_m": 10.0, "length_m": 14.0, "vertical_range_m": 10.0, "entrance_count": 1.0, "plate_number": "05-1032", "main_entrance_status": null, "access_description": "Od lugarnice na Velikom Lomu makadamskom cestom prema Zavižanu, skrenuti na prvom skretanju lijevo. Dalje tom cestom do okreteljke odakle planinarskom stazom prema Lubenovačkim vratima. Nakon što se staza počinje lagano uspinjati skrenuti lijevo prema grabenu strmo gore i u smjeru sjeveroistoka oko 1000 m zračne udaljenosti. Hodati po grebenu cca 100 m.", "technical_description": "Jednostavni vertikalni objekt. Do vertikalnog djela jame potrebno je postaviti prečnicu uz rub stijene nakon čega sljedi vertikala do dna jame.", "research_perspective": false, "research_perspective_note": "potpuno istražen;", "last_research_year": 2019.0, "last_research_date": "05.08.2019.", "last_research_date_iso": "2019-08-05", "clubs": "SOV; New Jersey Initial Response Team; BJBT; Speleo Roznava", "survey_authors": "Domagoj Čajko", "team_members": "David Rafael Lipovac; Vedran Ferenčak; Domagoj Čajko; Mark Dickey; Jessica Van Ord; Judit Kovács; Dénes Ákos Nagy", "hazards": "nema;", "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": null, "hydrogeology": null, "georef_record": null, "gps_tracklog": null, "note": null, "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-1032','da',NULL,NULL,NULL),
('1066','baza_velebit_2026_appready','Ribarka',44.7654546433031,15.0306345288147,'u_katastru','HR03646','u_katastru','jama','Ličko-senjska','Senj','Krasno','Hajdučki kukovi',26.1,28.0,NULL,'ok | Objekt u katastru','{"id": 1066, "name": "Ribarka", "cadastre_status": "u_katastru", "cadastral_number": "HR03646", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7654546433031, "lon": 15.0306345288147, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Hajdučki kukovi", "altitude_m": 1468.0, "depth_m": 26.1, "length_m": 28.0, "vertical_range_m": 26.1, "entrance_count": 1.0, "plate_number": "05-934", "main_entrance_status": null, "access_description": "Cestom od Krasnog krenuti prema velikom lomu na zapad. Nakon cca 3km skrenuti lijevo u šumu, stazom prema Lukinoj jami. Nakon 100m skrenuti sa staze i hodati još cca 400m u smjeru jugoistoka do kamenite vrtače. Po vrtači hodati još 150m u smjeru juga. Ulaz u jamu je vrlo mali, teško uočljiv, ispod stijene s isturenom glonđom.", "technical_description": "Ispred ulaza u jamu je crnogorično stablo pogodno za prirodno sidrište. Na ulazu treba postaviti devijator ili staviti bužir jer se jama stepenasto spušta prema dnu. Na policama ima sipara koji se trusi. U jami su 2 fiksa.", "research_perspective": false, "research_perspective_note": "potpuno istražen;", "last_research_year": 2020.0, "last_research_date": "08.08.2020.", "last_research_date_iso": "2020-08-08", "clubs": "SOV (2020.); PL (2000.)", "survey_authors": "Gorana Perić", "team_members": "2020.: Gorana Perić; Luka Ivančić; Hrvoje Mihalinec 2000.: A. Nowak; G. Muszalski", "hazards": "krušljive stijene", "pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "suh", "hydrogeology": "nema", "georef_record": "306518;Ribarka;383684.99999993306;4959433.999999905;0.7071067811865476", "gps_tracklog": null, "note": null, "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-934','da',NULL,NULL,'306518;Ribarka;383684.99999993306;4959433.999999905;0.7071067811865476'),
('1509','baza_velebit_2026_appready','Rildo',44.7596079292462,14.9874446373673,'u_katastru','HR02710','u_katastru','špilja','Ličko-senjska','Senj','Krasno','Crikvena',2.0,20.0,NULL,'ok | Objekt u katastru','{"id": 1509, "name": "Rildo", "cadastre_status": "u_katastru", "cadastral_number": "HR02710", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "špilja", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7596079292462, "lon": 14.9874446373673, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Crikvena", "altitude_m": null, "depth_m": 2.0, "length_m": 20.0, "vertical_range_m": 3.6, "entrance_count": 1.0, "plate_number": "05-843", "main_entrance_status": null, "access_description": "Od Lubenovca prema Krajačevom kuku planinarskom stazom. Po stazi se kreće u smjeru Zavižana do odvojka za vrh Crikvena i nastavi se u smjeru Zavižana. Nakon 50-ak m skrene se sa staze i krene spuštati prema vrtači. Jama se nalazi na rubu vrtače.", "technical_description": "Jednostavan horizontalni objekt. U špilji su pronađena medvjeđa &quot;gnijezda&quot;", "research_perspective": false, "research_perspective_note": "potpuno istražen", "last_research_year": 2017.0, "last_research_date": "4.8.2017", "last_research_date_iso": "2017-08-04", "clubs": "SKUZ; SOV", "survey_authors": "Tea Selaković", "team_members": "Tea Selaković; Anja Žmegač; Tin Takač; Tibor Bali; Vinka Dubovečak", "hazards": "medvjeđi brlog", "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": null, "hydrogeology": null, "georef_record": null, "gps_tracklog": null, "note": "U špilji postoji opasnost od susreta s medvjedom", "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-843','da',NULL,NULL,NULL),
('414','baza_velebit_2026_appready','Ričard Gir',44.7605197412173,14.9829113845755,'u_katastru','HR05062','u_katastru','jama','Ličko-senjska','Senj','Krasno','Premužićev toranj, Rožanski kukovi',36.0,40.0,NULL,'ok | Objekt na provjeri','{"id": 414, "name": "Ričard Gir", "cadastre_status": "u_katastru", "cadastral_number": "HR05062", "in_cadastre_bool": true, "not_in_cadastre_candidate": true, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7605197412173, "lon": 14.9829113845755, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Premužićev toranj, Rožanski kukovi", "altitude_m": 1508.0, "depth_m": 36.0, "length_m": 40.0, "vertical_range_m": 36.0, "entrance_count": 1.0, "plate_number": "05-1133", "main_entrance_status": null, "access_description": "Hodati Premužićevom stazom do Rossijeve kolibe. Kod Rossijeve kolibe skrenuti s Premužićeve staze na zapad planinarskom stazom za Velike Brisnice Hodati stazom cca 350 m, a zatim kada se dođe do ravnijeg terena skrenuti na jug te hodati po utabanoj staroj pastirskoj stazi označenom čunjićima cca 500 m u smjeru jugoistoka dok se ne stigne do široke staze u šumi podno stijena. Skrene se na sjever u stijene te se priječi po grebenu cca 20 metara do ulaza u jamu. Ulaz u jamu je slabo uočljiv, zaglonđan, uz stijene.", "technical_description": "Iznad ulaza postavljeno dvostruko sidrište s devijatorom oko stijene na suprotnoj strani. Ispod glonđe na ulazu dvostruko sidrište na ulazu u vertikalu. Do dna su postavljena još 3 međusidišta.", "research_perspective": false, "research_perspective_note": "potpuno istražen", "last_research_year": 2024.0, "last_research_date": "4.8.2024", "last_research_date_iso": "2024-08-04", "clubs": "SOV, SOŽ", "survey_authors": "Maja Marinić", "team_members": "Maja Marinić, Paula Skelin, Filip Milešević, Josip Dadić", "hazards": "nema", "pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "suh", "hydrogeology": "nema", "georef_record": null, "gps_tracklog": null, "note": null, "workflow_raw": "ok | Objekt na provjeri"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-1133','da',NULL,NULL,NULL),
