('535','baza_velebit_2026_appready','SOV 10',44.7357650875701,15.0306417996006,'nije_u_katastru',NULL,'nije_u_katastru','jama','Ličko-senjska','Senj','Krasno','Veliki Kozjak',25.0,42.0,'fotka;koordinate;plocica','fotka, koordinate, pločica','{"id": 535, "name": "SOV 10", "cadastre_status": "nije_u_katastru", "cadastral_number": null, "in_cadastre_bool": false, "not_in_cadastre_candidate": true, "record_status": "nije_u_katastru", "field_tasks": "fotka;koordinate;plocica", "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7357650875701, "lon": 15.0306417996006, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Veliki Kozjak", "altitude_m": 1470.0, "depth_m": 25.0, "length_m": 42.0, "vertical_range_m": 25.0, "entrance_count": 1.0, "plate_number": null, "main_entrance_status": null, "access_description": "Sjeverna strana zapadne skupine stijena velikog kozjaka. Autom od krasnog polja do planinarskog skloništa na velikom lubenovcu. Ide se markiranom stazom od velikog lubenovca prema vrhu velikog kozjaka. Nakon otprilike sat vremena hoda u zapadnoj skupini stijena velikog kozjaka skrene se desno u veliku vrtaču u kojoj se nalaze jame s oznakama sov 5, 6, 7 i 16. Iz vrtače se u smjeru sjevera prođe usjekom nazvanim obadova jaruga, prođe se sedlo i tu se na sjevernoj strani nalaze jame sov 3, 4, 8, 9 i 10.", "technical_description": "Nakon ulaznog dijela koji se polako suzuje slijedi uski dio širine 1,5 m nakon kojega se jama ponovno širi i mijenja smjer. Na toj razini nalazi se samo snijeg i led. Daljnji smjer ide prema pukotini koja se sužava i dalje se ne može proći bez klesanja. Osjeća se lagano strujanje zraka.", "research_perspective": true, "research_perspective_note": "potrebno proširivanje;", "last_research_year": 1997.0, "last_research_date": "31.07.1997.", "last_research_date_iso": "1997-07-31", "clubs": "SOV", "survey_authors": "Ljiljana Novosel", "team_members": "Ana Čop; Jagoda Munić; Ljiljana Novosel; Ivan Glavaš", "hazards": null, "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": "da", "hydrology": null, "hydrogeology": null, "georef_record": null, "gps_tracklog": null, "note": null, "workflow_raw": "fotka, koordinate, pločica"}'::jsonb,'sjeverni_velebit_2026_kml',FALSE,NULL,'da',NULL,NULL,NULL),
