('540','baza_velebit_2026_appready','SOV 17',44.732164776676,15.0404292596733,'nije_u_katastru',NULL,'nije_u_katastru','jama','Ličko-senjska','Senj','Krasno','Veliki Kozjak',8.0,14.0,'fotka;koordinate;plocica','fotka, koordinate, pločica','{"id": 540, "name": "SOV 17", "cadastre_status": "nije_u_katastru", "cadastral_number": null, "in_cadastre_bool": false, "not_in_cadastre_candidate": true, "record_status": "nije_u_katastru", "field_tasks": "fotka;koordinate;plocica", "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.732164776676, "lon": 15.0404292596733, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Veliki Kozjak", "altitude_m": 1440.0, "depth_m": 8.0, "length_m": 14.0, "vertical_range_m": 8.0, "entrance_count": 2.0, "plate_number": null, "main_entrance_status": null, "access_description": "Jama na izlazu iz smjera divokozina ispaša u istočnoj skupini stijena velikog kozjaka. Nalazi se u plitkoj jaruzi nasuprot ruba stijene. Pokraj nje vodi put obilježen plavim strelicama koji služi za silaz penjačima. Od skloništa na velikom lubenovcu na veliki kozjak", "technical_description": "JAMA SA RELATIVNO LAKIM ULAZOM KOJI SE POLAKO SUZUJE. NA DNU ULAZA NASTAVLJA SE VRLO USKI I NISKI KANAL KOJI SE GRANA. NA JEDNOM KRAJU ZAVRŠAVA USKIM KANALOM ZARUŠENIM KRUPNIM KAMENJEM.", "research_perspective": true, "research_perspective_note": "potrebno proširivanje;", "last_research_year": 1997.0, "last_research_date": "29.07.1997.", "last_research_date_iso": "1997-07-29", "clubs": "SOV", "survey_authors": "Ljiljana Josipović Novosel", "team_members": "Jagoda Munić; Mladen Novosel; Darko Štefanac; Ljiljana Novosel; Ivan Glavaš; Gordana Bartolić", "hazards": null, "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": "ne", "hydrology": null, "hydrogeology": null, "georef_record": null, "gps_tracklog": null, "note": null, "workflow_raw": "fotka, koordinate, pločica"}'::jsonb,'sjeverni_velebit_2026_kml',FALSE,NULL,'da',NULL,NULL,NULL),
('910','baza_velebit_2026_appready','SOV 35',44.7611915702902,15.0322457799315,'u_katastru','HR03334','u_katastru','jama','Ličko-senjska','Senj','Krasno','Hajdučki kukovi',24.0,29.0,NULL,'ok | Objekt u katastru','{"id": 910, "name": "SOV 35", "cadastre_status": "u_katastru", "cadastral_number": "HR03334", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7611915702902, "lon": 15.0322457799315, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Hajdučki kukovi", "altitude_m": null, "depth_m": 24.0, "length_m": 29.0, "vertical_range_m": 24.0, "entrance_count": 1.0, "plate_number": "05-882", "main_entrance_status": null, "access_description": "U Krasnom polju se krene glavnom šumskom asfaltiranom cestom prema Velikom Lomu. Dolazi se do raskrižja koje je na oštorom zavoju i skrene se desno u smjeru Zavižana. Na ovom raskrižju se skreće s asfaltirane ceste na makadam koji vodi do Zavižana te je postavljena rampa na ulazu u makadam. Prije Velikog Loma skrene se u šumu (put za Lubušku jamu i jamu Nedam) i ide uzbrdo. Nakn sto se dođe do vrha uzvisine skrene se desno i dođe do zaravni (stari logor Lubuške) i nastavi u smjeru jame Nedam. U blizini jame Nedam nalazi se ulaz u jamu.", "technical_description": "Skok od 15m sa snijegom na dnu. Prirodno sidrište i jedan fix.", "research_perspective": true, "research_perspective_note": "moguća perspektiva ako se otopi led", "last_research_year": 2006.0, "last_research_date": null, "last_research_date_iso": null, "clubs": "SOV; SUKZ", "survey_authors": "Marin Mašina", "team_members": "Van Staeyen Raf; Marin Mašina; Marijan Sutlović; Mislav Habijanec", "hazards": "nema;", "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": null, "hydrogeology": null, "georef_record": null, "gps_tracklog": null, "note": "6.2019- pronađena oznaka SOV35, skinute kooridnate. Jama završava snijegom, treba ju pogledati i nacrtati.The cave is located nearby Nedam Jama. Big entrance with visible ; snow on the bottom. Descend on three. Exploration by Van Staeyen Raf.To be checked on a other year when there is less snow ! ; Jama je istraživana 2006. tijekom ekspedicije međutim nije nacrtana. Nacrt digitalno uredila Ana Lipovac", "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-882','da',NULL,NULL,NULL),
('1521','baza_velebit_2026_appready','SOV 36',44.76186916805,15.0331507437833,'u_katastru','HR03306','u_katastru','jama','Ličko-senjska','Senj','Krasno','Hajdučki kukovi',27.6,30.7,NULL,'ok | Objekt u katastru','{"id": 1521, "name": "SOV 36", "cadastre_status": "u_katastru", "cadastral_number": "HR03306", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.76186916805, "lon": 15.0331507437833, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Hajdučki kukovi", "altitude_m": null, "depth_m": 27.6, "length_m": 30.7, "vertical_range_m": 27.6, "entrance_count": 1.0, "plate_number": "05-977", "main_entrance_status": null, "access_description": "Sjeveroistočna padina Hajdučkih kukova. Cestom od Krasnog prema Lomu. Na oštrom zavoju s lijeve strane šumskom vlakom uspinje se do vrha grebena (put za Lubušku jamu). Na platou se skrene prema jugu do logora Lubuške jame, pa po koordinatama 50m dalje.", "technical_description": "Jednostavna jama (tuba s manjom prostorijom i dimnjakom)", "research_perspective": true, "research_perspective_note": "nije poznato;", "last_research_year": 2019.0, "last_research_date": "01.08.2019.", "last_research_date_iso": "2019-08-01", "clubs": "SOV; SUKZ", "survey_authors": "Marin Mašina; Antonela Barbir", "team_members": "Antonela Barbir; Valentina Kraš; Marin Mašina; Marijan Sutlović; Ana Lipovac", "hazards": "nema;", "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": null, "hydrogeology": null, "georef_record": null, "gps_tracklog": null, "note": "Na dnu je ledeni čep", "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-977','da',NULL,NULL,NULL),
('548','baza_velebit_2026_appready','SOV 39',44.7553830726458,15.0235768213216,'nije_u_katastru',NULL,'nije_u_katastru','jama','Ličko-senjska','Senj','Krasno','Gornji kuk; Hajdučki kukovi',14.0,10.0,'fotka;koordinate','fotka, koordinate','{"id": 548, "name": "SOV 39", "cadastre_status": "nije_u_katastru", "cadastral_number": null, "in_cadastre_bool": false, "not_in_cadastre_candidate": true, "record_status": "nije_u_katastru", "field_tasks": "fotka;koordinate", "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7553830726458, "lon": 15.0235768213216, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Gornji kuk; Hajdučki kukovi", "altitude_m": 1420.0, "depth_m": 14.0, "length_m": 10.0, "vertical_range_m": 14.0, "entrance_count": 2.0, "plate_number": "05-0015", "main_entrance_status": null, "access_description": "Od velikog lubenovca prema gornjem kuku", "technical_description": "Mala jama s dva ulaza. Prvi ulaz promjera 1,5 m počinje pod crnogoričnim drvetom, zatim dolazi skok od 8 m na čijem je dnu snijeg. Do istog mjesta moglo bi se doći i kroz drugi ulaz po kosini. Nakon toga sljedi još jedan skok i snijegom pokrivena strmina. Sasvim pri dnu ulaz je u mali okrugli dimnjak.", "research_perspective": true, "research_perspective_note": "ne", "last_research_year": 1997.0, "last_research_date": "09.08.1997.", "last_research_date_iso": "1997-08-09", "clubs": "SOV", "survey_authors": "Ronald Železnjak", "team_members": null, "hazards": null, "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": "da", "hydrology": null, "hydrogeology": null, "georef_record": null, "gps_tracklog": null, "note": null, "workflow_raw": "fotka, koordinate"}'::jsonb,'sjeverni_velebit_2026_kml',FALSE,'05-0015','da',NULL,NULL,NULL),
('968','baza_velebit_2026_appready','SOV-HAD 25',44.736445189629,15.026849311952,'nije_u_katastru',NULL,'nije_u_katastru','jama','Ličko-senjska','Senj','Krasno','Veliki Kozjak',23.5,20.0,'ponoviti_nacrt','ponoviti nacrt | Ponoviti nacrt','{"id": 968, "name": "SOV-HAD 25", "cadastre_status": "nije_u_katastru", "cadastral_number": null, "in_cadastre_bool": false, "not_in_cadastre_candidate": true, "record_status": "nije_u_katastru", "field_tasks": "ponoviti_nacrt", "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.736445189629, "lon": 15.026849311952, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Veliki Kozjak", "altitude_m": 1460.0, "depth_m": 23.5, "length_m": 20.0, "vertical_range_m": 23.5, "entrance_count": 1.0, "plate_number": null, "main_entrance_status": null, "access_description": "Markaciju iz velikog lubenovca do velikog kozjaka slijedimo oko 40-ak minuta. Malo prije vrha pojavljuju se prve stijene i ovdje se skreće lijevo u veliku vrtaču gdje se nalaze jame sov 5, 6, 7 i 16. Iznad tih jama strmo se dižu stijene, ali na jednom mjestu postoji prijevoj obrastao travom. Kad se prijeđe taj prijevoj izađe se na sjevernu stranu velikog kozjaka. Ovdje zaobilazimo jame &quot;madrpusi&quot; i &quot;bejbi pusi&quot;. Iznad nas dižu se strme stijene, a ispod nas šuma se spušta prema velikom lubenovcu. Ovdje se moramo držati što bliže stijeni i hodati u pravcu zapada gdje ćemo poslje cca 250 m naići na jamu.", "technical_description": "Kroz ulaz od oko 5 x 5 m spustimo se 17 m po vertikali na kojoj se zadržava velika količina snijega. Odavde se jama račva u dva horizontalna i jedan vertikalan kanal dubine 3,5 m iznad kojeg su uglavljene kamene gromade. Iz tog vertikalnog dijela postoji jedan neprolazan kanal koji se opet malo širi. Od već spomenutih horizontalnih kanala jedan se pruža u pravcu sjevera i dug je 10 m, a drugi se pruža nešto strmije u pravcu juga i ovdje poslje skoka od 2 m nalazimo se na najdubljem dijelu jame.", "research_perspective": true, "research_perspective_note": "ne", "last_research_year": 1997.0, "last_research_date": "31.7.1997.", "last_research_date_iso": "1997-07-31", "clubs": "SOV", "survey_authors": "Ivan Glavaš", "team_members": "Ljiljana Novosel; Jagoda Munić; Ivan Glavaš; Gordana Bartolić; Ana Čop", "hazards": null, "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": "da", "hydrology": null, "hydrogeology": null, "georef_record": null, "gps_tracklog": null, "note": null, "workflow_raw": "ponoviti nacrt | Ponoviti nacrt"}'::jsonb,'sjeverni_velebit_2026_kml',FALSE,NULL,'da',NULL,NULL,NULL),
('1230','baza_velebit_2026_appready','Seka',44.74948952221,15.0070564444254,'u_katastru','HR02223','u_katastru','jama','Ličko-senjska','Senj','Krasno','Mali kuk; Rožanski kukovi',46.0,46.0,NULL,'ok | Objekt u katastru','{"id": 1230, "name": "Seka", "cadastre_status": "u_katastru", "cadastral_number": "HR02223", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.74948952221, "lon": 15.0070564444254, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Mali kuk; Rožanski kukovi", "altitude_m": 1350.0, "depth_m": 46.0, "length_m": 46.0, "vertical_range_m": 46.0, "entrance_count": 1.0, "plate_number": "05-797", "main_entrance_status": null, "access_description": "Od pastirskih stanova na lubenovcu u smjeru istoka prema malom kuku izrazito uzbrdo oko 500m, na prijevoju se zadržava isti smjer i spušta slijedećih 300m gdje se zaobilazi nepristupačan vertikalni stjenski zid prema velikoj vrtači promjera oko 100m, kada se zaobiđe zid okreće se u smjeru zapada, gdje je pristupačniji pristup i nakon 200m uzbrdo iz vrtače prema vrhu u izrazito stjenskom predjelu dolazi se do ulaza.", "technical_description": "Objekt je jama dubine 46 metara, te je potrebna oprema za ulazak u jamu. Pristup jami nije krušljiv niti postoje dodatne opasnosti od urušavanja, te jama nema hidroloških osobitosti niti leda. u blizini se nalazi i druga jama pod nazivom Braco, ali one nisu povezane u sustav. U jami se ne nalazi smeće, niti minske naprave.", "research_perspective": false, "research_perspective_note": "ne", "last_research_year": 2017.0, "last_research_date": "23.-28.6.2017.", "last_research_date_iso": null, "clubs": "SOV; SKUZ; Bulgarian Federation of Speleology", "survey_authors": "2017: Aneliya Pavlova", "team_members": "Aneliya Pavlova; Marko Ličko; Ana Bakšić; Ela Kovač; Luana Lojić; Vinka Dubovečak", "hazards": null, "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": null, "hydrogeology": null, "georef_record": null, "gps_tracklog": null, "note": null, "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-797','da',NULL,NULL,NULL),
('112','baza_velebit_2026_appready','Senilna jama',44.7658694083297,15.0050427895901,'u_katastru','HR04201','u_katastru','jama','Ličko-senjska','Senj','Krasno','Hajdučki kukovi',150.0,289.0,NULL,'ok | Objekt u katastru','{"id": 112, "name": "Senilna jama", "cadastre_status": "u_katastru", "cadastral_number": "HR04201", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7658694083297, "lon": 15.0050427895901, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Hajdučki kukovi", "altitude_m": 1512.0, "depth_m": 150.0, "length_m": 289.0, "vertical_range_m": 150.0, "entrance_count": 2.0, "plate_number": "05-1059; 05-1060", "main_entrance_status": null, "access_description": "U Krasnom Polju se kod pilane skrene na asfaltiranu cestu u smjeru juga te se nakon otprilike pola sata (17 km) dolazi do Careve Kuće (planinarska kuća PD Gromovača iz Otočca). Kod Careve kuće skrene se desno u smjeru jugozapada na makadamski put prema Alanu. Vozimo se otprilike 4 km i nakon križa skrenemo desno, prođemo rampu i dolazimo velike krške udoline - Veliki Lubenovac. Od Velikog Lubenovca makadamom prema Lubenovačkim vratima do okretaljke. Dalje se krene uspinjati u smjeru sjeverozapada prema Vratarskom kuku po vrletnom terenu. Nakon 400 m dolazi se do glavnog ulaza u jamu s kojeg je vidljiva polica a ako se nastavi po izohipsi u smjeru sjevera dolazi se i do drugog ulaza u jamu koji je široka pukotina.", "technical_description": "Jednostavni vertikalna jama sa dva ulaza. Glavnom ulazu (ulaz Troha) pristupa sa osiguravanjem na prirodno sidrište te nakon vertikale od 110 m spušta se u dvoranu sa ledom.. U istu dvoranu moguće je pristupiti i kroz drugi ulaz (ulaz Damir). Kroz tja ulaz prvo slijedi manja poilca iza koje ide vertikala od 100 m do dvorane s ledom. Na jugu dvorane nalazi se neprolazno suženje., dok se na zapadu napreduje u dubinu još 50 m te spušta na ledeni čep. Jama je opremljena fiksevima 8 mm, te je za opremanje kroz oba ulaza potrebno imati karabinere i pločice za 21 sidrište te 100 užeta.", "research_perspective": true, "research_perspective_note": "nastavlja se provlačenjem; led", "last_research_year": 2022.0, "last_research_date": "6.8.2022.", "last_research_date_iso": "2022-08-06", "clubs": "SOV; SD Proteus", "survey_authors": "Marko Ličko", "team_members": "Darko Troha; Dora Troha; Marko Ličko; Lea Okićki; Roko Željem; Vesna Troha; Sanja Đurin; Jagoda Munić; Nini Legović; Olga Jerković - Perić", "hazards": "led", "pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "nakapnica/prokapnica", "hydrogeology": "nema", "georef_record": "309513;Senilna jama;381659.9999999267;4959516.999999895;0.7071067811865476", "gps_tracklog": null, "note": "Jama ima perspektivu istraživanja dalje ukoliko dođe do dodatnog topljenja leda", "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-1059; 05-1060','da',NULL,NULL,'309513;Senilna jama;381659.9999999267;4959516.999999895;0.7071067811865476'),
('1231','baza_velebit_2026_appready','Sestrica 1',44.7592548846473,14.9920516284106,'nije_u_katastru',NULL,'nije_u_katastru','jama','Ličko-senjska','Senj','Krasno','Rožanski kukovi',5.5,5.5,NULL,'ok | Ako se otopi led možda postane objekt','{"id": 1231, "name": "Sestrica 1", "cadastre_status": "nije_u_katastru", "cadastral_number": null, "in_cadastre_bool": false, "not_in_cadastre_candidate": true, "record_status": "nije_u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7592548846473, "lon": 14.9920516284106, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Rožanski kukovi", "altitude_m": 1538.0, "depth_m": 5.5, "length_m": 5.5, "vertical_range_m": 5.5, "entrance_count": 1.0, "plate_number": "05-791", "main_entrance_status": null, "access_description": "Od logora krenuti prema Premužićevoj i nakon prvog grebena krenuti na desno, prijeći po ''mostu'' između 2 vrtače i spustiti se na lijevo. Zračna linija ima 300m, pola sata hoda.", "technical_description": "Postavljeno je ulazno dvostruko sidrište sa spitovima.", "research_perspective": true, "research_perspective_note": "nastavlja se spuštanejm, nastavlja se preko vodenog tijela,cijeli kompleks Sestrica trebalo bi pogledati kad se otopi snijeg jer su vjerojatno spojene", "last_research_year": 2023.0, "last_research_date": "9.8.2023", "last_research_date_iso": "2023-08-09", "clubs": "SOV; SUKZ", "survey_authors": "Marta Malenica", "team_members": "Luka Havliček; Natalija Kos; Vinka Dubovečak; Marta Malenica", "hazards": "nema", "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": "da", "hydrology": null, "hydrogeology": null, "georef_record": null, "gps_tracklog": null, "note": "NIJE OBJEKT; objekte Sestrica 1,2 i 3 potrebno je ponovno provjeriti za 5 godina", "workflow_raw": "ok | Ako se otopi led možda postane objekt"}'::jsonb,'sjeverni_velebit_2026_kml',FALSE,'05-791','da',NULL,NULL,NULL),
('1232','baza_velebit_2026_appready','Sestrica 2',44.7590516338241,14.9923348028863,'u_katastru','HR02072','u_katastru','jama','Ličko-senjska','Senj','Krasno','Crikvena; Rožanski kukovi',11.0,22.0,NULL,'ok | Objekt u katastru','{"id": 1232, "name": "Sestrica 2", "cadastre_status": "u_katastru", "cadastral_number": "HR02072", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7590516338241, "lon": 14.9923348028863, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Crikvena; Rožanski kukovi", "altitude_m": 1559.0, "depth_m": 11.0, "length_m": 22.0, "vertical_range_m": 11.0, "entrance_count": 1.0, "plate_number": "05-792", "main_entrance_status": null, "access_description": "Jama Sestrica 2 se nalazi blizu dna druge vrtače istočno od Premužićeve staze i vrha Crikvene (oko 350 m zračne udaljenosti). Pristup vrtači je s njene jugoistočne strane. Do dna vrtače se hoda lagano, blizu dna vrtača nalazi se visoka vegetacija (zbog postojanja šumske sjene i visoke relativne vlage). Jamu je lagano naći zbog postojanja hladnog strujanja zraka. Do ulaza u Sestricu 2 mora se proći do „mostiću“ s čije lijeve strane se nalazi ulaz u jamu Sestrica 1. Pokraj Sestrice 2 se nalazi i ulaz u jamu Sestrica 3. Na dnu ima snijeg/led.", "technical_description": "Jednostavna jama. Potrebna oprema za tehničko napredovanje", "research_perspective": true, "research_perspective_note": "nastavlja se penjanjem;", "last_research_year": 2023.0, "last_research_date": "9.8.2023", "last_research_date_iso": "2023-08-09", "clubs": "SOV; SUK; HBSD", "survey_authors": "Nikolina Kos", "team_members": "Luka Havliček; Vinka Dubovečak; Marta Malenica; Nikolina Kos", "hazards": "nema;", "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": "da", "hydrology": null, "hydrogeology": null, "georef_record": null, "gps_tracklog": null, "note": "U Blizini Sestrice 2 nalaze se još dva objekta, Sestrica 1 i Sestrica 3. Sve jame imaju led na dnu stoga postoji mogućnost da su jame spojene međutim zbog postojanja leda ne može se točno ustvrditi.", "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-792','da',NULL,NULL,NULL),
('1233','baza_velebit_2026_appready','Sestrica 3',44.7591770844455,14.9922936460546,'nije_u_katastru',NULL,'nije_u_katastru','jama','Ličko-senjska','Senj','Krasno','Rožanski kukovi',9.0,15.6,NULL,'ok | Ako se otopi led možda postane objekt','{"id": 1233, "name": "Sestrica 3", "cadastre_status": "nije_u_katastru", "cadastral_number": null, "in_cadastre_bool": false, "not_in_cadastre_candidate": true, "record_status": "nije_u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7591770844455, "lon": 14.9922936460546, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Rožanski kukovi", "altitude_m": 1531.0, "depth_m": 9.0, "length_m": 15.6, "vertical_range_m": 9.0, "entrance_count": 1.0, "plate_number": "05-772", "main_entrance_status": null, "access_description": "Od Rossijeve kolibe hodati Premužićevom stazom prema Alanu. Nakon Crikvene hodati stazom još 150 m a potom skrenuti sa staze na istok te hodati još 100 m te skrenuti na SI prema vrtači i hodati još 200 m do dna vrtače. Jama se nalazi na istočnom obronku vrtače između jama Sestrice blizanke i Sestrica 2.", "technical_description": "Jednostavni vertikalni objekt sa snijegom na dnu. Za opremanje je potrebno uže od 20 m, gurtna i karabiner za prirodno sidrište i 1 bužir.", "research_perspective": true, "research_perspective_note": "ledeni čep", "last_research_year": 2023.0, "last_research_date": "9.8.2023", "last_research_date_iso": "2023-08-09", "clubs": "SOV; SUKZ", "survey_authors": "2023: Gorana Perić 2017: Marta Malenica", "team_members": "2023: Gorana Perić, Luka Ivančić 2017: Luka Havliček; Vinka Dubovečak; Nikolina Kos; Marta Malenica", "hazards": "nema", "pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": "da", "hydrology": "nakapnica/prokapnica", "hydrogeology": "nema", "georef_record": null, "gps_tracklog": null, "note": null, "workflow_raw": "ok | Ako se otopi led možda postane objekt"}'::jsonb,'sjeverni_velebit_2026_kml',FALSE,'05-772','da',NULL,NULL,NULL),
('1306','baza_velebit_2026_appready','Sestrice blizanke',44.7593131988359,14.9923785243583,'u_katastru','HR02050','u_katastru','jama','Ličko-senjska','Senj','Krasno','Rožanski kukovi',68.0,157.0,NULL,'ok | Objekt u katastru','{"id": 1306, "name": "Sestrice blizanke", "cadastre_status": "u_katastru", "cadastral_number": "HR02050", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7593131988359, "lon": 14.9923785243583, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Rožanski kukovi", "altitude_m": 1572.0, "depth_m": 68.0, "length_m": 157.0, "vertical_range_m": 68.0, "entrance_count": 2.0, "plate_number": "05-806", "main_entrance_status": null, "access_description": "Jama Sestrice blizanke se nalazi blizu dna druge vrtače istočno od Premužićeve staze i vrha Crikvene (oko 350 m zračne udaljenosti). Pristup vrtači je s njene jugoistočne strane. Do dna vrtače se hoda lagano, blizu dna vrtača nalazi se visoka vegetacija (zbog postojanja šumske sjene i visoke relativne vlage). Jamu je lagano naći zbog postojanja hladnog strujanja zraka. Do jamskih ulaza u Sestrice Blizanke mora se proći između ulaza u druge jame (radnih naziva Sestrica 1, Sestrica 2 te Sestrica 3.", "technical_description": "Jama ima dva ulaza te se kroz oba ulaza može spustiti. Tehnički detalji za opremanje objekta naznačeni su na nacrtu. Sa postojećih fikseva skinute su matice i podlošci.", "research_perspective": true, "research_perspective_note": "nastavlja se penjanjem; nastavlja se provlačenjem; ledeni čep", "last_research_year": 2023.0, "last_research_date": "9.8.2023", "last_research_date_iso": "2023-08-09", "clubs": "SOV; SUKZ; HBSD", "survey_authors": "2023: Gorana Perić 2017:Vinka Dubovečak", "team_members": "2023: Lukas Grbac Lacković, Paul Karoshi, Gorana Perić, Luka Ivančić, Danilo Dobrić 2017: Luka Havliček; Marta Malenica; Nikolina Kos; Vinka Dubovečak", "hazards": "led;", "pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": "da", "hydrology": "nakapnica/prokapnica", "hydrogeology": "nema", "georef_record": null, "gps_tracklog": null, "note": "U jami se nalazi velika količina snijega i leda čijim bi otapanjem jama postala jako perspektivna. Najperspektivnija je najdublja vertikala (mjerna točka 19 - 20), za koju je pretpostavka da je povezana s vertikalom iz upitnika između mjernih točaka 15 i 16. Također perspektiva postoji u kanalu iznad ledenih saljeva u donjoj dvorani (mjerna točka 18) (kosina koju je potrebno ispenjati preko leda). Manji upitnik postoji u toj donjoj dvorani s njene sjeverne strane (dolje lijevo ukoliko je osoba okrenuta prema ledenim saljevima). Upitnici su prikazani u priloženom dokumentu: Sestrice blizanke profil sa fotografijama", "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-806','da',NULL,NULL,NULL),
('1202','baza_velebit_2026_appready','Sirena',44.7681051030322,14.9875639426746,'u_katastru','HR00572','u_katastru','jama','Ličko-senjska','Senj','Krasno','Rožanski kukovi',401.0,1075.0,NULL,'ok | Objekt u katastru','{"id": 1202, "name": "Sirena", "cadastre_status": "u_katastru", "cadastral_number": "HR00572", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7681051030322, "lon": 14.9875639426746, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Rožanski kukovi", "altitude_m": 1543.0, "depth_m": 401.0, "length_m": 1075.0, "vertical_range_m": 401.0, "entrance_count": 2.0, "plate_number": "05-327", "main_entrance_status": null, "access_description": "Pristup jami je sjeverno od Rossijeve kolibe Premužićevom stazom, nakon 200 m skreće se lijevo u prvu ponikvu strmim prilazom. U ponikvi su dva ulaza iz kojih se osjeća jako strujanje zraka (jama Sirena i jama Mala Sirena).", "technical_description": "Za ulaz u jamu Sirenu treba slobodno ispenjati 10 m nakon čega se uđe u malu ulaznu dvoranu što predstavlja špiljski ulaz jame (iznad tog špiljskog ulaza također postoji i vertikalni ulaz, no on se ne koristi za ulazak u jamu). Jama je složena i grana se na oko 120 m u tri vertikale, jedna završava na 230 m dubine, druga na 263 m dubine i treća na 401 m dubine.", "research_perspective": true, "research_perspective_note": "nastavlja se penjanjem; potrebno proširivanje;", "last_research_year": 2014.0, "last_research_date": null, "last_research_date_iso": null, "clubs": "SD Ursus Spelaeus; SOV; SUK Bratislava; SKOL; SUKZ; ASAK; SOB; SOŽ; SK Aenigma; SOM; SU Höhlenbären; SPC Breganja; SD Istra; SK Sophia; C. Martel-Abime Nicois", "survey_authors": "Campijeva ledenica 1980: Jadranko Ostojić Sirena 2004-2014: Bakšić; M. Čepelak; A. Perušić; M. Radanović; M. Rakovac; T. Selaković; R. Železnjak; A. Žmegač", "team_members": "1980: Jadranko Ostojić; Srđan Đukić Branislav Šmída; Marcel Griflík; Erik Kapucian; Zoltán Ágh; Jozef Ondruška; Marek Audy; Inga Patarčić; Luka Mudronja; Darko Bakšić; Đuro Mileusnić; Matej Radanović; Lovro Čepelak; Andrija Perušić; Marko Rakovac; Dmitrije Pavlinov - Papi; Kardi ŽupanićM; Ronald Železnjak; Katja Milišić; Marin Glušević; Yavor Tsvetanov; Matija Čepelak; Petra Kovač-Konrad; Iva Vuković; Vladimir Milutinović - Kobi; Dmitrije Dimitrijević - Mičko; Nenad Suvajac; Mario Olšavski; Ana Bakšić; Dalibor Paar; Vinka Dubovečak; Tanja Šinko; Georg Pacher; Paul Karoshi; Ivana Erak; Marko Erak; Stjepan Dubac; Laura Tamoševiče; Tea Selaković; Ilija Jurak; Anja Žmegač; Drago Novak; Alen Kirin – Galon; Renata Rogić; Marta Malenica; Luka Havliček; Dino Grozić; Valentina Ćukušić; Ivica Ćukušić; Vladimir Ranković; Tomislav Skender; Marijan Sutlović; Ana Stojčević; Edo Vričić", "hazards": "nema;", "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": null, "hydrogeology": null, "georef_record": null, "gps_tracklog": null, "note": "Iz zapisnika istraživanja 1980.: Ulaz je kosina sa snijegom 21 m vertikale kosa dvorana puna leda i još 2 m dolje snijeg i led.", "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-327','da',NULL,NULL,NULL),
('1576','baza_velebit_2026_appready','Skoro Poputna',44.7681688041692,15.0310457664697,'u_katastru','HR03411','u_katastru','jama s kratkim špiljskim ulazom','Ličko-senjska','Senj','Krasno','Hajdučki kukovi',7.8,11.5,NULL,'ok | Objekt u katastru','{"id": 1576, "name": "Skoro Poputna", "cadastre_status": "u_katastru", "cadastral_number": "HR03411", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama s kratkim špiljskim ulazom", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7681688041692, "lon": 15.0310457664697, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Hajdučki kukovi", "altitude_m": 1357.0, "depth_m": 7.8, "length_m": 11.5, "vertical_range_m": 7.8, "entrance_count": 1.0, "plate_number": "05-1001", "main_entrance_status": null, "access_description": "Iz Krasnog Polja vozimo se glavnom asfaltiranom cestom prema jugu (Štirovača, Zavižan). Nakon ~13 km u oštrom zavoju s desne strane se odvaja makadam s rampom koji ulazi u NP Sjeverni Velebit i koji vodi prema Zavižanu (postavljeni drveni putokazi). Nakon što se prođe rampa prati se makadam te dolazi do lugarnice na Malom lomu. 4 km nakon lugarnice na Malom lomu parkira se uz cestu te krene uzbrdo po strmoj kosini u šumu. Nakon 100 m dolazi se do litice u čijem se podnožju sa sjeveroistočne strane nalazi se slabo uočljiv ulaz u jamu.", "technical_description": "Jama započinje kratkim špiljskim ulazom dužine 1-2metra nakon kojeg slijedi strmija kosina i vertikala. Pod ulaza i samog dna prekriven je kamenjem i glonđama. Vertikala se nastavlja do dna, bez polica. Prisutan bočni kanal koji je također ispunjen kamenjem. Prilikom opremanja drvo iznad ulaza u jamu je poslužilo kao prirodno sidrište, te nisu rađena međusidrišta. Osim toga, bila su potrebna dva bužira.", "research_perspective": false, "research_perspective_note": "potpuno istražen;", "last_research_year": 2020.0, "last_research_date": "26.07.2020.", "last_research_date_iso": "2020-07-26", "clubs": "SOV; SKOL", "survey_authors": "Maja Marinić", "team_members": "Marina Grandić; Maja Marinić; Velimir Ivačić", "hazards": "nema", "pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "nakapnica", "hydrogeology": "nema", "georef_record": null, "gps_tracklog": null, "note": null, "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-1001','da',NULL,NULL,NULL),
('621','baza_velebit_2026_appready','Skočifiks',44.7651603672977,14.9901420432884,'u_katastru','HR05001','u_katastru','jama','Ličko-senjska','Senj','Krasno','Jerković dolac, Rožanski kukovi',19.5,21.9,NULL,'ok | Objekt na provjeri','{"id": 621, "name": "Skočifiks", "cadastre_status": "u_katastru", "cadastral_number": "HR05001", "in_cadastre_bool": true, "not_in_cadastre_candidate": true, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7651603672977, "lon": 14.9901420432884, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Jerković dolac, Rožanski kukovi", "altitude_m": 1542.0, "depth_m": 19.5, "length_m": 21.9, "vertical_range_m": 19.5, "entrance_count": 1.0, "plate_number": "05-1137", "main_entrance_status": null, "access_description": "Jama se nalazi na JI obronku vrtače istočno od Premužićeve staze kod Rossijeve kolibe na sjevernom Velebitu. Od Rossijeve kolibe krenuti istočno 150 m prrema dnu vrtače. Hodati po izohipsi 50 m. Ulaz se nalazi ispod visoke stijene, okružen klekovinom.", "technical_description": "Jednostavna jama s ledenim čepom na dnu. Potrebno je periodički provjeravati stanje leda.", "research_perspective": true, "research_perspective_note": "moguće napredovanje u slučaju topljenja ledenog čepa", "last_research_year": 2024.0, "last_research_date": "31.7.2024", "last_research_date_iso": "2024-07-31", "clubs": "SOV, SUKZ", "survey_authors": "Hrvoje Đurinski", "team_members": "Hrvoje Đurinski, Gorana Perić, Filip Milešević, Vedran Ferenčak, Dorijan Cikač", "hazards": "nema", "pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": "da", "hydrology": "suh", "hydrogeology": "nema", "georef_record": null, "gps_tracklog": null, "note": null, "workflow_raw": "ok | Objekt na provjeri"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-1137','da',NULL,NULL,NULL),
