('922','baza_velebit_2026_appready','Tomina jasena (Matežnovac)',44.8040389162157,15.0684379137678,'u_katastru','HR03252','u_katastru','jama','Ličko-senjska','Senj','Krasno','Matežinovac; Stražbenica',98.0,114.0,NULL,'ok | Objekt u katastru','{"id": 922, "name": "Tomina jasena (Matežnovac)", "cadastre_status": "u_katastru", "cadastral_number": "HR03252", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.8040389162157, "lon": 15.0684379137678, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Matežinovac; Stražbenica", "altitude_m": 1171.0, "depth_m": 98.0, "length_m": 114.0, "vertical_range_m": 98.0, "entrance_count": 1.0, "plate_number": "05-912", "main_entrance_status": null, "access_description": "Iz smjera Krasnog krenuti u smjeru Apatišana. Prije planinarske kuće skrenuti oštro desno gdje je rampa. Proći rampu te nakon 3,3 km dolazi se do jame koje je udaljena 2 metra od šumske ceste. 98b šumsko područje.", "technical_description": "Jednostavna vertikalna jama s policom na 70m. Na polici se nalazi minsko eksplozivno sredstvo. Iduća vetikala vodi do dna jame", "research_perspective": false, "research_perspective_note": "potpuno istražen;", "last_research_year": 2019.0, "last_research_date": "02.08.2019.", "last_research_date_iso": "2019-08-02", "clubs": "SOV; SOŽ; Northern New Jersey Grotto", "survey_authors": "Marko Ličko", "team_members": "2019.- Marko Ličko; Tibor Bali; David Rafael Lipovac; Carl Heitmeyer; Mark Chai; Vedran Ferenčak 1981. - Jadranko Ostojić; Srđan Đukić", "hazards": "minsko-eksplozivna sredstva;", "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": null, "hydrogeology": null, "georef_record": null, "gps_tracklog": null, "note": null, "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-912','da',NULL,NULL,NULL),
('969','baza_velebit_2026_appready','Torov čekić',44.7652965630113,15.0358431593093,'krug_14',NULL,'na_provjeri','jama','Ličko-senjska','Senj','Krasno','Hajdučki kukovi',14.0,18.0,'ponoviti_nacrt','ponoviti nacrt | Ponoviti nacrt','{"id": 969, "name": "Torov čekić", "cadastre_status": "krug_14", "cadastral_number": null, "in_cadastre_bool": false, "not_in_cadastre_candidate": true, "record_status": "na_provjeri", "field_tasks": "ponoviti_nacrt", "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7652965630113, "lon": 15.0358431593093, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Hajdučki kukovi", "altitude_m": 1395.0, "depth_m": 14.0, "length_m": 18.0, "vertical_range_m": 14.0, "entrance_count": 1, "plate_number": "05-851", "main_entrance_status": null, "access_description": "Jama se nalazi na sjeveroistočnim obroncima Hajdučkih kukova na sjevernom Velebitu. U Krasnom polju se krene glavnom šumskom asfaltiranom cestom prema Velikom Lomu. Dolazi se do raskrižja koje je na oštrom zavoju i skrene se desno u smjeru Zavižana. Na ovom raskrižju se skreće s asfaltirane ceste na makadam koji vodi do Zavižana te je postavljena rampa na ulazu u makadam. Neposredno nakon što se prođe Mali Lom a prije lugarnice na Velikom lomu skrene se u lijevo u šumu (smjer JZ) odnosno prate se oznake koje su postavili speleolozi za put prema Lubuškoj i jami Nedam. Nakon 400 m skrene se s puta prema oštroj padni u smjeru JI. Ulaz u jamu lako je uočljiv kada se popne na padinu i nalazi se desno od ulaza u jamu Bateryka.", "technical_description": "Jednostavni vertikalni objekt pukotinskog karaktera. Ulaz je zaglonđan.", "research_perspective": true, "research_perspective_note": "potpuno istražen", "last_research_year": 2025, "last_research_date": "4.8.2025", "last_research_date_iso": "2025-08-04", "clubs": "SOV, SUE", "survey_authors": "Petra Jagodić", "team_members": "Petra Jagodić, Gorana Perić, Luka Peloza, Paula Skelin, Dino Grozić", "hazards": "nema", "pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "nakapnica/prokapnica", "hydrogeology": "nema", "georef_record": "321003;Torov čekić;384096.9999999342;4959408.999999907;0.7071067811865476", "gps_tracklog": null, "note": "Jamu su prvi puta istražili poljski speleolozi 2000. godine", "workflow_raw": "ponoviti nacrt | Ponoviti nacrt"}'::jsonb,'sjeverni_velebit_2026_kml',FALSE,'05-851','da',NULL,NULL,'321003;Torov čekić;384096.9999999342;4959408.999999907;0.7071067811865476'),
