('542','baza_velebit_2026_appready','Vulkan',44.7317135145603,15.0382185660546,'nije_u_katastru',NULL,'nije_u_katastru','jama','Ličko-senjska','Senj','Krasno','Veliki Kozjak',53.0,17.5,'fotka;koordinate;plocica','fotka, koordinate, pločica','{"id": 542, "name": "Vulkan", "cadastre_status": "nije_u_katastru", "cadastral_number": null, "in_cadastre_bool": false, "not_in_cadastre_candidate": true, "record_status": "nije_u_katastru", "field_tasks": "fotka;koordinate;plocica", "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7317135145603, "lon": 15.0382185660546, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Veliki Kozjak", "altitude_m": 1525.0, "depth_m": 53.0, "length_m": 17.5, "vertical_range_m": 53.0, "entrance_count": 1.0, "plate_number": null, "main_entrance_status": null, "access_description": "Jama se nalazi u istočnoj skupini velikog kozjaka. Autom od krasnog polja cestom do velikog lubenovca. Od skloništa na lubenovcu markiranom stazom na vrh velikog kozjaka, a odavde u istočnu skupinu.", "technical_description": "Ulaznom vertikalom od 43 m dođe se u manju dvoranu. Slijedi snježna kosina kojom se spusti na &quot;snježni most&quot;. Odavde se može spustiti i na lijevu i na desnu stranu. Oba odvojka završavaju snijegom. Nije primjećen nikakav prolaz ali postoji mogućnost da se usljed topljenja snijega otvori.", "research_perspective": true, "research_perspective_note": "da-uslijed otapanja snijega", "last_research_year": 1996.0, "last_research_date": "21.07.1996.", "last_research_date_iso": "1996-07-21", "clubs": "SOV", "survey_authors": "Darko Bakšić", "team_members": "Darko Bakšić; Ana Čop; Damir Lacković", "hazards": null, "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": "da", "hydrology": null, "hydrogeology": null, "georef_record": null, "gps_tracklog": null, "note": "U zapisniku piše da Darko Bakšić i Damir Lacković imaju fotke. Provjeriti stanje leda", "workflow_raw": "fotka, koordinate, pločica"}'::jsonb,'sjeverni_velebit_2026_kml',FALSE,NULL,'da',NULL,NULL,NULL),
('1104','baza_velebit_2026_appready','Xantipa',44.7667335490765,14.9981987355201,'u_katastru','HR02225','u_katastru','jama','Ličko-senjska','Senj','Krasno','Vratarski kuk; Rožanski kukovi',323.0,400.0,NULL,'ok | Objekt u katastru','{"id": 1104, "name": "Xantipa", "cadastre_status": "u_katastru", "cadastral_number": "HR02225", "in_cadastre_bool": true, "not_in_cadastre_candidate": false, "record_status": "u_katastru", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7667335490765, "lon": 14.9981987355201, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Vratarski kuk; Rožanski kukovi", "altitude_m": 1650.0, "depth_m": 323.0, "length_m": 400.0, "vertical_range_m": 323.0, "entrance_count": 1.0, "plate_number": "05-888", "main_entrance_status": null, "access_description": "Ogromna megadepresija Xantipe ispod Vratarskog kuka.", "technical_description": "Ogromna otvorena vrtača čiji gornji vanjski promjer prelazi 200 m, a na dnu vrtače se nalazi led i prolaz u niže, pretežito vertikalne dijelove jame. Za pristup potrebno je uže 100m koje se postavlja u smjeru juga niz strme padine preko klekovine. Na vertikalnom dijelu koji slijedi je dvostruko sidrište, a za doseći dno vrtače/jame potrebno je uže od 100m do prve police, a zatim se od police krene 10m prema rubu i potrebno je uže od 50tak m do dna vrtače. Dno vrtače/jame je dimenzija 40m x 25m te se zadržava snijeg/led kroz čitavu godinu. U najnižem dijelu vrtače led se spušta u otvor dimenzija 5x5 koji ide zajedno sa ledenom sigom vertikalno u dubinu 100m. Daljnje napredovanje kroz objekt potrebno nastaviti uz oprez i procjenu sigurnosti i stabilnosti leda, te je potrebno okvirno još 150 m užeta. U djelovima jame ispod leda nalaze se fiksevi i spitevi koji su prekriveni ledom.", "research_perspective": true, "research_perspective_note": "snijeg", "last_research_year": 2023.0, "last_research_date": "1.8.2023", "last_research_date_iso": "2023-08-01", "clubs": "SLOVACI", "survey_authors": "Branislav Šmida", "team_members": "Griflik M; Sanja Ćirić; Erik Kapucian; Kreutz E; Karol Kyška; Branislav Šmida; Jan Vykoupil", "hazards": "9", "pollution": null, "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "nakapnica/prokapnica", "hydrogeology": "nema", "georef_record": null, "gps_tracklog": null, "note": null, "workflow_raw": "ok | Objekt u katastru"}'::jsonb,'sjeverni_velebit_2026_kml',TRUE,'05-888','da',NULL,NULL,NULL),
