('1596','baza_velebit_2026_appready','Jamica s pogledom na Velikom Rajincu',44.7762971927215,15.0339857699813,'krug_14',NULL,'na_provjeri','špilja s jamskim ulazom','Ličko-senjska','Senj','Krasno','Veliki Rajinac, Sjeverni Velebit',7.0,11.5,NULL,NULL,'{"id": 1596, "name": "Jamica s pogledom na Velikom Rajincu", "cadastre_status": "krug_14", "cadastral_number": null, "in_cadastre_bool": false, "not_in_cadastre_candidate": null, "record_status": "na_provjeri", "field_tasks": null, "object_type_final": "špilja s jamskim ulazom", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7762971927215, "lon": 15.0339857699813, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Veliki Rajinac, Sjeverni Velebit", "altitude_m": 1442.0, "depth_m": 7.0, "length_m": 11.5, "vertical_range_m": 7.0, "entrance_count": 2, "plate_number": "05-1179", "main_entrance_status": null, "access_description": "Špilja se nalazi u Lomskoj dulibi na Sjevernom Velebitu na zapadnom obronku Velikog Rajinca. Na makadamskoj cesti auto se parkira između Roguša i Lekčevca na vidljivom ugibalištu sa strane. Krene se u dulibu prema Ledenoj jami, ali umjesto prema jami skrene se blago udesno prema brdu. Na najlakšem dijelu skrene se s travnjaka prema šumi. Potrebno je popeti se 190 m nadmorske visine prateći koordinate. Špilja se nalazi nešto dalje od Mjesečevog meandra, blizu goli stijena s kojih se pruža lijep pogledm prema Hajdučkim kukovima. Ulaz je vidljiv tek iz blizine.", "technical_description": "Ulaz se nalazi na manjem platou masivne stijene s koje se vide Hajdučki kukovi. Desno od ulaza je stijena visine 5 m. Ulaz se spušta usko i na samom ulazu je skok od 3 m za kojeg nije potrebna oprema. Špiljski kanal se strmo spušta i prekriven je lišćem i humusom i dolazi se do dna odakle se proteže niz špranjica dubine 2 m. Na dnu se vidi vanjsko svjetlo.", "research_perspective": null, "research_perspective_note": "potpuno istražen", "last_research_year": 2025, "last_research_date": "31.7.2025", "last_research_date_iso": "2025-07-31", "clubs": "SOV", "survey_authors": "Ema Buljan", "team_members": "Ema Buljan, Dragana Rajković, Dalibor Paar", "hazards": "nema", "pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "nakapnica/prokapnica", "hydrogeology": "nema", "georef_record": "321011;Jamica s pogledom na Velikom Rajincu;383971.9999999338;4960633.999999907;0.7071067811865476", "gps_tracklog": null, "note": "jama je imala oznaku A1", "workflow_raw": null}'::jsonb,'sjeverni_velebit_2026_kml',FALSE,'05-1179','da',NULL,NULL,'321011;Jamica s pogledom na Velikom Rajincu;383971.9999999338;4960633.999999907;0.7071067811865476'),
