('1614','baza_velebit_2026_appready','Puževa smrt',44.7692699763681,15.0411246060445,'krug_14',NULL,'na_provjeri','jama','Ličko-senjska','Senj','Krasno','Mali Lom, Sjeverni Velebit',40.0,43.0,NULL,NULL,'{"id": 1614, "name": "Puževa smrt", "cadastre_status": "krug_14", "cadastral_number": null, "in_cadastre_bool": false, "not_in_cadastre_candidate": null, "record_status": "na_provjeri", "field_tasks": null, "object_type_final": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "lat": 44.7692699763681, "lon": 15.0411246060445, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Mali Lom, Sjeverni Velebit", "altitude_m": 1315.0, "depth_m": 40.0, "length_m": 43.0, "vertical_range_m": 40.0, "entrance_count": 1, "plate_number": "05-1205", "main_entrance_status": null, "access_description": "Makadamskom cestom od Velikog Loma ići prema Malom Lomu. Voziti 10 minutam proći prvi veći zavoj koji se uspinje i onda kad se ponovno počinje spuštati parkirati na proširenju. Hodati 60m od makadama do jame kroz šumu.", "technical_description": "Jama se nalazi na škrapovitom terenu. Jedna od škrapi se otvara u kružnu vertikalu 6m dubine. Na SI rubu se vertikala sužava na uži prolaz dalje 15m dublje do police koja dijeli jamu u dvije paralelne vertikale od 21, odnosno 19m. Ova dublja se otvara u prostor 5 x 2. 2m prije dna se plića vertikala spaja na dublju. Dno je prekriveno blatom i glonđama. Nema perspektive.", "research_perspective": null, "research_perspective_note": "potpuno istražen", "last_research_year": 2025, "last_research_date": "2.8.2025", "last_research_date_iso": "2025-08-02", "clubs": "SOV, SOL, SUE, ASAK", "survey_authors": "Lovel Kukuljan", "team_members": "Mateja Dimitrijević, Luka Bogdanić, Marko Ličko, Jakov Rešetar, Lovel Kukuljan, Marina Grandić", "hazards": "nema", "pollution": "nema", "digital_survey_status": "da", "bibliography_status": null, "ice_present": null, "hydrology": "nakapnica/prokapnica", "hydrogeology": "nema", "georef_record": "321053;Puževa smrt;384522.9999999355;4959842.99999991;0.7071067811865476", "gps_tracklog": null, "note": null, "workflow_raw": null}'::jsonb,'sjeverni_velebit_2026_kml',FALSE,'05-1205','da',NULL,NULL,'321053;Puževa smrt;384522.9999999355;4959842.99999991;0.7071067811865476'),
